-- =============================================================================
-- 515 — LE CAHIER D'EXERCICES DE 1RE (partie 3)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/1re/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 515 --niveau 1re --fichiers allemand.n1 --suffixe 3 > supabase/contenu/515_exercices_1re_3.sql
--
-- 36 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   allemand.n1             36 exercices · 12 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('4113f286-ddf7-57a8-9154-2816837bdad1'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Sur la carte : des fleuves et des villes","competence":"lire-carte","situation":"Pour son exposé, Nele prépare une carte des grands fleuves d’Europe centrale. Observe-la : les noms des fleuves sont écrits en allemand.","documents":[{"id":"carte","type":"carte","titre":"Flüsse in Mitteleuropa","fond":"europe","cadrage":[-2,43.5,27,56],"fleuves":["rhin","danube","elbe","oder"],"frontieres":true,"lieux":[{"id":"z1","lieu":"strasbourg","symbole":"point","nom":"Strasbourg","teinte":"violet"},{"id":"z2","lieu":"hambourg","symbole":"point","nom":"Hambourg","teinte":"violet"},{"id":"z3","lieu":"vienne-autriche","symbole":"point","nom":"Vienne","teinte":"violet"},{"id":"z4","lieu":"budapest","symbole":"point","nom":"Budapest","teinte":"violet"},{"id":"z5","lieu":"belgrade","symbole":"point","nom":"Belgrade","teinte":"violet"}],"etiquettes":[{"texte":"Rhein","lon":5.2,"lat":49.6,"style":"ville"},{"texte":"Elbe","lon":12,"lat":52.6,"style":"ville"},{"texte":"Oder","lon":15.4,"lat":52.2,"style":"ville"},{"texte":"Donau","lon":12,"lat":48.6,"style":"ville"}],"source":"Carte simplifiée, fleuves tirés du cours"}],"questions":[{"enonce":"Touche le grand port situé près de l’endroit où l’Elbe se jette dans la mer du Nord.","aide":"Suis le tracé de l’Elbe vers le nord-ouest, jusqu’à la mer.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche la ville française située sur le Rhin, face à Kehl : le pont de l’Europe les relie.","aide":"Le Rhin est la frontière entre la France et l’Allemagne : cherche la ville française au bord du fleuve.","type":"zone","document":"carte","multiple":false},{"enonce":"Quel fleuve, écrit en allemand sur la carte, traverse Vienne, Budapest et Belgrade ?","aide":"Regarde quel nom longe les trois villes ; il commence par un D.","type":"texte","placeholder":"En allemand"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"C’est **Hambourg** : le grand port allemand de l’Elbe, à quelques dizaines de kilomètres de la mer du Nord."},{"cle":{"type":"zone","ids":["z1"]},"explication":"**Strasbourg** est sur la rive française du Rhin ; le pont de l’Europe la relie à Kehl, en Allemagne."},{"cle":{"type":"texte","acceptes":["donau","die donau","danube","le danube"]},"affichage":"Donau","explication":"C’est **die Donau**, le Danube : il traverse dix pays et quatre capitales, dont Vienne, Budapest et Belgrade."}]$ex$::jsonb),
  ('4113f286-ddf7-57a8-9154-2816837bdad1'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Herbst 2015 : Freiwillige am Bahnhof","competence":"analyser-texte","situation":"Pour son cours d’allemand, Hanna lit un article sur la façon dont des habitants ont accueilli des réfugiés en 2015. À toi de relever ce qui compte.","documents":[{"id":"artikel","type":"texte","genre":"article","titre":"Willkommen am Bahnhof","blocs":["Im Herbst 2015 kamen mehr als eine Million Flüchtlinge nach Deutschland. An vielen Bahnhöfen warteten Freiwillige mit Wasser, Kleidern und Spielzeug für die Kinder. Man sprach von einer „Willkommenskultur“.","Die Kanzlerin Angela Merkel sagte damals: „Wir schaffen das.“ Aber nicht alle waren froh: Manche Menschen hatten Angst, und eine Partei gegen die Einwanderung wurde stärker.","Heute ist die Integration eine tägliche Aufgabe. Man muss die Sprache lernen, zur Schule gehen und Arbeit finden."],"source":"Article écrit pour l’exercice, d’après le cours"}],"questions":[{"enonce":"Touche le mot allemand qui désigne les bénévoles qui attendent les réfugiés dans les gares.","aide":"Ce sont des personnes qui aident sans être payées : le mot est dans le premier paragraphe.","type":"zone","document":"artikel","multiple":false},{"enonce":"Range chaque information dans la bonne colonne, d’après l’article.","aide":"Le premier et le deuxième paragraphe racontent 2015 ; le dernier parle d’aujourd’hui.","type":"categories","categories":[{"id":"c0","texte":"L’accueil en 2015"},{"id":"c1","texte":"Les défis d’aujourd’hui"}],"items":[{"id":"i0","texte":"Aller à l’école"},{"id":"i1","texte":"Trouver un travail"},{"id":"i2","texte":"Des bénévoles attendent dans les gares"},{"id":"i3","texte":"Apprendre la langue"},{"id":"i4","texte":"De l’eau, des vêtements et des jouets sont distribués"}]},{"enonce":"Complète la dernière phrase de l’article.","aide":"Pour s’intégrer, que faut-il faire avec la langue du pays ?","type":"trous","segments":["Man muss die Sprache ",0,", zur Schule gehen und Arbeit finden."],"banque":["vergessen","verbieten","verkaufen","lernen"]},{"enonce":"Relie chaque mot allemand du vocabulaire du cours à sa traduction.","aide":"*Willkommenskultur* contient l’idée d’*Aufnahme*.","type":"association","gauche":[{"id":"g0","texte":"die Aufnahme"},{"id":"g1","texte":"die Integration"},{"id":"g2","texte":"der Austausch"},{"id":"g3","texte":"die Vielfalt"}],"droite":[{"id":"d0","texte":"l’intégration"},{"id":"d1","texte":"l’échange"},{"id":"d2","texte":"la diversité"},{"id":"d3","texte":"l’accueil"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m15"]},"explication":"Les **Freiwillige** sont les bénévoles : ils accueillent les arrivants avec de l’eau, des vêtements et des jouets."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c1","i4":"c0"}},"explication":"En **2015**, on distribue de l’aide dans les gares ; **aujourd’hui**, l’intégration passe par la langue, l’école et le travail."},{"cle":{"type":"trous","trous":[["lernen"]]},"affichage":"lernen","explication":"Il faut **die Sprache lernen** : apprendre la langue est le premier pas de l’intégration."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"**die Aufnahme** = l’accueil, **die Integration** = l’intégration, **der Austausch** = l’échange, **die Vielfalt** = la diversité."}]$ex$::jsonb),
  ('4113f286-ddf7-57a8-9154-2816837bdad1'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Bargeld, Mark und Euro","competence":"analyser-document","situation":"Lena compare ce que dit son grand-père de l’argent avec quelques repères historiques. Lis les deux documents.","documents":[{"id":"reperes","type":"tableau","titre":"Geld und Geschichte","colonnes":["Repère","Jahr","Was er bedeutet"],"lignes":[["Die Fuggerei in Augsburg",1521,"älteste Sozialsiedlung, noch bewohnt"],["Die D-Mark",1948,"Symbol für Wirtschaftswunder und Stabilität"],["Der Euro",2002,"Die Europäische Zentralbank sitzt in Frankfurt"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice, d’après le cours"},{"id":"chat","type":"dialogue","modele":"sms","titre":"Nachrichten","participants":[{"nom":"Lena","emoji":"👧","cote":"gauche"},{"nom":"Opa Karl","emoji":"👴","cote":"droite"}],"repliques":[{"qui":"Lena","texte":"Opa, warum zahlst du im Supermarkt immer mit Bargeld? Ich zahle mit der Karte."},{"qui":"Opa Karl","texte":"Wir sagen: „Nur Bares ist Wahres.“ Ich will sehen, was ich ausgebe, und ich spare lieber."},{"qui":"Lena","texte":"Aber der Euro ist doch ein modernes Geld!"},{"qui":"Opa Karl","texte":"Ja, aber ich habe noch die D-Mark im Kopf."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot allemand qui désigne l’argent liquide, que préfère le grand-père.","aide":"Il paie « en liquide » : le mot est dans le premier message de Lena.","type":"zone","document":"chat","multiple":false},{"enonce":"Touche la case qui donne l’année de la Fuggerei d’Augsbourg, la plus ancienne cité sociale encore habitée.","aide":"Cherche la ligne « Die Fuggerei », puis la colonne « Jahr ».","type":"zone","document":"reperes","multiple":false},{"enonce":"Combien d’années séparent l’introduction de la D-Mark de celle de l’euro ?","aide":"Soustrais les deux années de la colonne « Jahr ».","type":"nombre","unite":"ans"},{"enonce":"Pourquoi le grand-père reste-t-il fidèle au liquide ?","aide":"Relis la réponse d’Opa Karl au proverbe.","type":"choix","options":[{"id":"a","texte":"Il veut voir ce qu’il dépense et préfère épargner"},{"id":"b","texte":"Il travaille pour la Banque centrale européenne à Francfort"},{"id":"c","texte":"Il n’a jamais entendu parler de l’euro en Allemagne"},{"id":"d","texte":"Il pense que la carte bancaire est interdite en Allemagne"}],"multiple":false},{"enonce":"Range ces trois repères du plus ancien au plus récent. Le premier est « Fuggerei ».","aide":"Les années sont dans la colonne « Jahr » du tableau.","type":"ordre","items":[{"id":"a","texte":"Einführung der D-Mark"},{"id":"b","texte":"Fuggerei"},{"id":"c","texte":"Einführung des Euro"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8"]},"explication":"**Bargeld** désigne l’argent liquide, les espèces. Le proverbe « *Nur Bares ist Wahres* » dit : seul le liquide est vrai."},{"cle":{"type":"zone","ids":["r0c1"]},"explication":"La Fuggerei date de **1521** : elle a été fondée par le banquier Jakob Fugger."},{"cle":{"type":"nombre","valeur":54,"tolerance":0},"affichage":"54 ans","explication":"2002 − 1948 = **54 ans**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Il dit : « Ich will sehen, was ich ausgebe, und ich spare lieber. » Les Allemands restent **attachés aux espèces et à l’épargne**."},{"cle":{"type":"ordre","ids":["b","a","c"]},"explication":"**1521** (Fuggerei) → **1948** (D-Mark) → **2002** (euro)."}]$ex$::jsonb),
  ('3ac783e3-7a43-5c51-b685-18bfe2989ee5'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les grandes dates du vivre-ensemble","competence":"se-reperer-temps","situation":"Pour le journal du lycée, Jonas dresse une frise de quelques dates qui comptent dans l’histoire de la tolérance et des droits en Allemagne.","documents":[{"id":"frise","type":"frise","titre":"Zusammenleben in Deutschland","debut":1760,"fin":2040,"pas":40,"periodes":[],"evenements":[{"id":"z1","date":1779,"nom":"Nathan"},{"id":"z2","date":1919,"nom":"Hirschfeld"},{"id":"z3","date":1949,"nom":"Grundgesetz"},{"id":"z4","date":1994,"nom":"§ 175 weg"},{"id":"z5","date":2017,"nom":"Ehe für alle"}],"source":"Dates tirées du cours"}],"questions":[{"enonce":"Touche l’événement qui correspond à la Loi fondamentale, dont l’article 3 interdit toute discrimination.","aide":"*Grundgesetz* veut dire « Loi fondamentale » : repère le nom sur la frise.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent la suppression définitive du paragraphe 175 du mariage pour tous ?","aide":"Le paragraphe 175 punissait l’homosexualité. Soustrais les deux dates de la frise.","type":"nombre","unite":"ans"},{"enonce":"Complète la phrase sur la dernière date de la frise.","aide":"Le nom de l’événement est écrit sur la frise.","type":"trous","segments":["Seit 2017 gibt es die ",0," für alle."],"banque":["Ehe","Arbeit","Wahl","Schule"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"La **Grundgesetz** (Loi fondamentale) date de **1949**."},{"cle":{"type":"nombre","valeur":23,"tolerance":0},"affichage":"23 ans","explication":"2017 − 1994 = **23 ans**."},{"cle":{"type":"trous","trous":[["ehe"]]},"affichage":"Ehe","explication":"**die Ehe für alle** : le mariage pour tous, adopté en Allemagne en 2017."}]$ex$::jsonb),
  ('3ac783e3-7a43-5c51-b685-18bfe2989ee5'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un club ouvert à tous","competence":"analyser-document","situation":"Mehmet cherche un club de sport près de chez lui. Il découvre l’affiche d’une association. Lis-la attentivement.","documents":[{"id":"affiche","type":"fiche","modele":"affiche","entete":"TSV Sonnental","sousTitre":"Der Verein für alle","emoji":"⚽","teinte":"violet","lignes":[{"texte":"Fußball, Schwimmen und Tanzen für Kinder und Erwachsene","id":"z1"},{"separateur":true},{"texte":"Auch Menschen mit Behinderung sind willkommen: Inklusionstraining jeden Mittwoch","id":"z2"},{"texte":"Jedes Jahr wählen die Mitglieder den Vorstand.","id":"z3"},{"texte":"Mitglied werden: nur 5 Euro im Monat","id":"z4"}],"pied":"Komm vorbei und mach mit!","source":"Affiche écrite pour l’exercice"}],"questions":[{"enonce":"Touche la ligne qui montre que le Verein est une « école de démocratie » : on y vote.","aide":"Cherche la ligne où les membres « wählen » (élisent) quelqu’un.","type":"zone","document":"affiche","multiple":false},{"enonce":"Touche la ligne qui parle d’inclusion des personnes handicapées.","aide":"Le mot allemand pour « handicap » est *Behinderung*.","type":"zone","document":"affiche","multiple":false},{"enonce":"Complète la règle de l’article 3 de la Loi fondamentale (depuis 1994).","aide":"Le verbe veut dire « défavoriser », et il est au participe II.","type":"trous","segments":["Niemand darf wegen seiner Behinderung ",0," werden."],"banque":["gewählt","engagiert","benachteiligt","geholfen"]},{"enonce":"Ces activités relèvent-elles du sport ou de la vie démocratique du club ?","aide":"*abstimmen* veut dire « voter ».","type":"categories","categories":[{"id":"c0","texte":"Le sport"},{"id":"c1","texte":"La vie démocratique"}],"items":[{"id":"i0","texte":"Tanzen"},{"id":"i1","texte":"Bei der Mitgliederversammlung abstimmen"},{"id":"i2","texte":"Den Vorstand wählen"},{"id":"i3","texte":"Schwimmen"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"« Jedes Jahr **wählen** die Mitglieder den Vorstand » : on élit le bureau chaque année, c’est un geste démocratique."},{"cle":{"type":"zone","ids":["z2"]},"explication":"La ligne sur le **Inklusionstraining** accueille les personnes avec un handicap (*Behinderung*)."},{"cle":{"type":"trous","trous":[["benachteiligt"]]},"affichage":"benachteiligt","explication":"**benachteiligt** : « Personne ne doit être défavorisé à cause de son handicap. »"},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0"}},"explication":"Danser et nager sont des **activités sportives** ; élire le bureau et voter en assemblée sont la **vie démocratique** de l’association."}]$ex$::jsonb),
  ('3ac783e3-7a43-5c51-b685-18bfe2989ee5'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Les trois anneaux et le chemin des droits","competence":"argumenter","situation":"Pour un exposé sur la tolérance, Sophie résume la parabole des trois anneaux de Lessing, puis elle relève quelques étapes de l’histoire des droits.","documents":[{"id":"ring","type":"texte","genre":"recit","titre":"Die Ringparabel","blocs":["Ein Vater liebt seine drei Söhne gleich. Er hat einen Ring und lässt zwei identische Ringe machen. Jeder Sohn bekommt einen Ring.","Nach seinem Tod streiten die Söhne: Welcher Ring ist der echte? Ein Richter antwortet: Man kann es nicht sehen. Jeder soll durch sein Handeln zeigen, dass sein Ring der echte ist.","So erzählt Lessing 1779 von den drei Religionen: Judentum, Christentum und Islam."],"source":"Résumé rédigé pour l’exercice, d’après Lessing, Nathan der Weise (1779)"},{"id":"recht","type":"tableau","titre":"Rechte und Verfolgung","colonnes":["Jahr","Ereignis"],"lignes":[[1919,"Magnus Hirschfeld gründet in Berlin ein Institut für Sexualwissenschaft"],[1933,"Die Nazis plündern das Institut"],[1994,"Der Paragraf 175 wird endgültig abgeschafft"],[2017,"Die „Ehe für alle“ wird eingeführt"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice, d’après le cours"}],"questions":[{"enonce":"Touche le mot allemand qui dit comment chaque fils doit prouver la valeur de son anneau.","aide":"Le juge ne demande pas des paroles, mais des actes.","type":"zone","document":"ring","multiple":false},{"enonce":"Quelle idée la parabole des anneaux défend-elle ?","aide":"Aucun anneau ne se distingue des deux autres à l’œil nu.","type":"choix","options":[{"id":"a","texte":"Chaque religion se juge à la conduite de ses fidèles"},{"id":"b","texte":"Les religions doivent être interdites pour éviter les disputes"},{"id":"c","texte":"Une seule religion est la vraie et les deux autres sont fausses"},{"id":"d","texte":"Le plus âgé des fils a raison parce qu’il est l’aîné"}],"multiple":false},{"enonce":"Touche la case qui donne l’année de la suppression définitive du paragraphe 175.","aide":"Cherche la ligne qui parle de « Paragraf 175 » et lis son année.","type":"zone","document":"recht","multiple":false},{"enonce":"Combien d’années séparent le pillage de l’institut de Hirschfeld par les nazis de la suppression du paragraphe 175 ?","aide":"Prends l’année du pillage (« plündern ») et celle de la suppression.","type":"nombre","unite":"ans"},{"enonce":"Relie chaque mot allemand à sa traduction.","aide":"*gleich* veut dire « égal » ; *Recht*, « droit ».","type":"association","gauche":[{"id":"g0","texte":"die Toleranz"},{"id":"g1","texte":"sich engagieren"},{"id":"g2","texte":"die Gleichberechtigung"},{"id":"g3","texte":"benachteiligen"}],"droite":[{"id":"d0","texte":"la tolérance"},{"id":"d1","texte":"l’égalité des droits"},{"id":"d2","texte":"défavoriser"},{"id":"d3","texte":"s’engager"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m45"]},"explication":"Chacun doit prouver la valeur de son anneau par son **Handeln**, c’est-à-dire par sa conduite, ses actes."},{"cle":{"type":"choix","ids":["a"]},"explication":"Lessing défend la **tolérance** : on ne peut pas dire quelle religion est la seule vraie, c’est la conduite de chacun qui compte."},{"cle":{"type":"zone","ids":["r2c0"]},"explication":"Le paragraphe 175, qui punissait l’homosexualité, est supprimé définitivement en **1994**."},{"cle":{"type":"nombre","valeur":61,"tolerance":0},"affichage":"61 ans","explication":"1994 − 1933 = **61 ans**."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g3":"d2","g1":"d3"}},"explication":"**die Toleranz** = la tolérance, **sich engagieren** = s’engager, **die Gleichberechtigung** = l’égalité des droits, **benachteiligen** = défavoriser."}]$ex$::jsonb),
  ('3a3d7cda-bd71-5e16-9be7-5037c20715a9'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"1933 – 1937 : quatre ans de culture sous contrôle","competence":"se-reperer-temps","situation":"Pour son dossier sur l’art sous le IIIe Reich, Paul place quelques événements sur une frise. Observe-la.","documents":[{"id":"frise","type":"frise","titre":"Kunst und Macht","debut":1932,"fin":1938,"pas":1,"periodes":[{"id":"z1","debut":1933,"fin":1938,"nom":"Drittes Reich","teinte":"corail"}],"evenements":[{"id":"z2","date":1933,"nom":"Bücherverbrennung"},{"id":"z3","date":1935,"nom":"Triumph des Willens"},{"id":"z4","date":1937,"nom":"Entartete Kunst"}],"source":"Dates tirées du cours"}],"questions":[{"enonce":"Touche l’exposition qui ridiculisait l’art moderne, appelée « Art dégénéré ».","aide":"« Dégénéré » se dit *entartet* en allemand.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent les autodafés de l’exposition « Art dégénéré » ?","aide":"Autodafé se dit *Bücherverbrennung* : lis sa date sur la frise.","type":"nombre","unite":"ans"},{"enonce":"Complète la date des autodafés de 1933.","aide":"Le cours donne la date exacte : le 10 mai 1933.","type":"trous","segments":["Die Bücherverbrennung war am 10. ",0," 1933."],"banque":["Oktober","Juli","Mai","März"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z4"]},"explication":"L’exposition **Entartete Kunst**, à Munich en **1937**, ridiculisait l’art moderne."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4 ans","explication":"1937 − 1933 = **4 ans**."},{"cle":{"type":"trous","trous":[["mai"]]},"affichage":"Mai","explication":"Les autodafés ont eu lieu le **10 mai 1933** : des étudiants brûlent les livres d’auteurs juifs, pacifistes, communistes."}]$ex$::jsonb),
  ('3a3d7cda-bd71-5e16-9be7-5037c20715a9'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le cabaret d’Erika Mann","competence":"analyser-texte","situation":"Johanna prépare une fiche sur ceux qui ont résisté à la dictature par le rire ou par l’exil. Elle part d’un petit texte.","documents":[{"id":"text","type":"texte","genre":"article","titre":"Lachen gegen die Macht","blocs":["Im Januar 1933 eröffnet Erika Mann in München das Kabarett „Die Pfeffermühle“. Auf der Bühne macht sich die Gruppe über die Nazis lustig.","Bald wird das in Deutschland zu gefährlich. Die Gruppe spielt weiter in der Schweiz.","Ihr Bruder Thomas Mann lebt in den USA. Im Radio der BBC spricht er zu den Deutschen. Bertolt Brecht geht zuerst nach Dänemark."],"source":"Texte écrit pour l’exercice, d’après le cours"}],"questions":[{"enonce":"Touche le mot allemand qui désigne le spectacle satirique d’Erika Mann.","aide":"C’est une vieille tradition allemande de théâtre politique et humoristique.","type":"zone","document":"text","multiple":false},{"enonce":"Pourquoi le cabaret quitte-t-il l’Allemagne ?","aide":"Relis le deuxième paragraphe : le mot *gefährlich* signifie « dangereux ».","type":"choix","options":[{"id":"a","texte":"Erika Mann doit rejoindre son frère aux États-Unis"},{"id":"b","texte":"Le public allemand ne s’intéressait plus du tout au cabaret"},{"id":"c","texte":"Jouer ces moqueries devient dangereux sous les nazis"},{"id":"d","texte":"Le cabaret a été invité à jouer à la radio de la BBC"}],"multiple":false},{"enonce":"Range chaque artiste ou chaque geste dans la bonne colonne.","aide":"Deux gestes consistent à quitter le pays, deux autres à monter sur scène.","type":"categories","categories":[{"id":"c0","texte":"L’exil"},{"id":"c1","texte":"Le rire contre le pouvoir"}],"items":[{"id":"i0","texte":"La troupe de la Pfeffermühle se moque des nazis sur scène"},{"id":"i1","texte":"Bertolt Brecht part d’abord au Danemark"},{"id":"i2","texte":"Thomas Mann parle aux Allemands par la radio de la BBC"},{"id":"i3","texte":"Erika Mann ouvre un cabaret à Munich"}]},{"enonce":"Relie chaque mot allemand à sa traduction.","aide":"*verbrennen* veut dire « brûler ».","type":"association","gauche":[{"id":"g0","texte":"die Macht"},{"id":"g1","texte":"die Zensur"},{"id":"g2","texte":"das Exil"},{"id":"g3","texte":"die Bücherverbrennung"}],"droite":[{"id":"d0","texte":"l’exil"},{"id":"d1","texte":"la censure"},{"id":"d2","texte":"l’autodafé"},{"id":"d3","texte":"le pouvoir"}]}]}$ex$::jsonb,
