  ('3a3d7cda-bd71-5e16-9be7-5037c20715a9'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Brûler, interdire, partir","competence":"analyser-document","situation":"Pour un exposé, Nils a rédigé une page sur le 10 mai 1933 et dressé un tableau d’artistes partis en exil. Lis les deux documents.","documents":[{"id":"vortrag","type":"texte","genre":"article","titre":"Der 10. Mai 1933","blocs":["Am 10. Mai 1933 verbrennen Studenten in vielen Städten Bücher von jüdischen, pazifistischen und kommunistischen Autoren.","Schon viel früher hatte Heinrich Heine geschrieben: „Dort, wo man Bücher verbrennt, verbrennt man auch am Ende Menschen.“","Joseph Goebbels ist der Minister für Propaganda. Wer nicht Mitglied der Reichskulturkammer ist, darf nicht mehr arbeiten."],"source":"Texte écrit pour l’exercice ; la phrase de Heine est citée dans le cours"},{"id":"exil","type":"tableau","titre":"Künstler im Exil","colonnes":["Name","Weg","Was er oder sie tut"],"lignes":[["Thomas Mann","USA","spricht zu den Deutschen im BBC-Radio"],["Bertolt Brecht","Dänemark, dann USA","schreibt und warnt im Exil"],["Marlene Dietrich","Ausland","weigert sich, für die Nazis zu drehen"],["Erika Mann","Schweiz","spielt dort ihr Kabarett weiter"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice, d’après le cours"}],"questions":[{"enonce":"Touche le mot allemand qui désigne ce dont Goebbels est le ministre.","aide":"Le mot ressemble beaucoup au français.","type":"zone","document":"vortrag","multiple":false},{"enonce":"Touche la case qui dit par quel pays Brecht est passé avant de rejoindre les États-Unis.","aide":"Cherche la ligne « Bertolt Brecht », colonne « Weg ».","type":"zone","document":"exil","multiple":false},{"enonce":"Pourquoi cite-t-on la phrase de Heine à propos des autodafés ?","aide":"Relis la citation : après les livres, qui brûle-t-on ?","type":"choix","options":[{"id":"a","texte":"Elle montre que brûler des livres annonce la violence contre les hommes"},{"id":"b","texte":"Elle prouve que Heine approuvait les autodafés de 1933"},{"id":"c","texte":"Elle explique que les nazis ont censuré l’imprimerie de Heine"},{"id":"d","texte":"Elle dit que l’art n’a aucun rapport avec la politique"}],"multiple":false},{"enonce":"Relie chaque personne à ce qu’elle a fait, d’après les documents et le cours.","aide":"Les deux premiers sont dans les documents ; pour Riefenstahl, pense au film de 1935.","type":"association","gauche":[{"id":"g0","texte":"Joseph Goebbels"},{"id":"g1","texte":"Thomas Mann"},{"id":"g2","texte":"Erika Mann"},{"id":"g3","texte":"Leni Riefenstahl"}],"droite":[{"id":"d0","texte":"poursuit son cabaret en Suisse"},{"id":"d1","texte":"dirige la propagande du régime"},{"id":"d2","texte":"réalise Le Triomphe de la volonté"},{"id":"d3","texte":"parle aux Allemands par la BBC"}]},{"enonce":"Dans le tableau, Marlene Dietrich est-elle restée tourner pour le régime nazi ?","aide":"Relis la dernière colonne de sa ligne.","type":"choix","options":[{"id":"a","texte":"Non : elle refuse de tourner pour les nazis"},{"id":"b","texte":"Oui : elle y tourne tous ses films"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m40"]},"explication":"Goebbels est le ministre de la **Propaganda** : il contrôle la culture et l’information."},{"cle":{"type":"zone","ids":["r1c1"]},"explication":"Brecht passe par le **Danemark** avant les États-Unis."},{"cle":{"type":"choix","ids":["a"]},"explication":"Heine avait écrit : « Là où l’on brûle des livres, on finit par brûler des hommes. » La phrase **annonce** la violence qui suivra."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g3":"d2","g1":"d3"}},"explication":"**Goebbels** dirige la propagande, **Thomas Mann** parle à la BBC, **Erika Mann** joue en Suisse, **Riefenstahl** réalise *Le Triomphe de la volonté* (1935)."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le tableau dit qu’elle **se refuse** (*weigert sich*) à tourner pour les nazis."}]$ex$::jsonb),
  ('df3653fa-11c0-5d35-8dbc-8b016a39d690'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Quatre inventions, quatre dates","competence":"lire-tableau","situation":"Pour le club de sciences, Mira a dressé un tableau de quelques découvertes venues des pays germanophones. Lis-le.","documents":[{"id":"tab","type":"tableau","titre":"Erfinder und Entdecker","colonnes":["Wer","Was","Wann"],"lignes":[["Johannes Gutenberg","der Buchdruck","um 1450"],["Wilhelm Conrad Röntgen","die Röntgenstrahlen",1895],["Carl Benz","das Automobil",1886],["Robert Koch","der Tuberkulose-Erreger",1882]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice, d’après le cours"}],"questions":[{"enonce":"Touche la case qui donne l’année du brevet de l’automobile de Carl Benz.","aide":"Cherche la ligne « Carl Benz », puis la colonne « Wann ».","type":"zone","document":"tab","multiple":false},{"enonce":"Combien d’années séparent la découverte du bacille de la tuberculose par Koch de celle des rayons X par Röntgen ?","aide":"Soustrais les deux années du tableau.","type":"nombre","unite":"ans"},{"enonce":"Range ces inventions de la plus ancienne à la plus récente. La première est « der Buchdruck ».","aide":"Compare les années de la dernière colonne.","type":"ordre","items":[{"id":"a","texte":"der Buchdruck"},{"id":"b","texte":"das Automobil"},{"id":"c","texte":"die Röntgenstrahlen"},{"id":"d","texte":"der Tuberkulose-Erreger"}]}]}$ex$::jsonb,
