  ('df3653fa-11c0-5d35-8dbc-8b016a39d690'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Lise Meitner, la grande oubliée","competence":"analyser-texte","situation":"Pour un exposé sur les femmes scientifiques, Leonie lit un court texte sur la physicienne Lise Meitner.","documents":[{"id":"meitner","type":"texte","genre":"article","titre":"Lise Meitner","blocs":["Lise Meitner stammt aus Österreich. Als Physikerin arbeitet sie in Berlin mit einem Kollegen an der Radioaktivität.","Als Jüdin muss sie 1938 Deutschland verlassen. 1939 erklärt sie mit ihrem Neffen Otto Frisch die Kernspaltung.","Den Nobelpreis für Chemie erhält aber Otto Hahn allein. Heute trägt ein chemisches Element ihren Namen: das Meitnerium."],"source":"Texte écrit pour l’exercice, d’après le cours"}],"questions":[{"enonce":"Touche le mot allemand qui désigne la fission nucléaire, que Lise Meitner explique en 1939.","aide":"Le mot est composé de *Kern* (noyau) et d’un nom qui veut dire « division ».","type":"zone","document":"meitner","multiple":false},{"enonce":"Touche le nom du chercheur qui reçoit seul le prix Nobel de chimie.","aide":"Il est nommé dans le dernier paragraphe, avec son prénom Otto.","type":"zone","document":"meitner","multiple":false},{"enonce":"Complète la phrase d’après le texte.","aide":"Après un verbe de modalité comme *muss*, le second verbe est à l’infinitif.","type":"trous","segments":["Als Jüdin muss sie 1938 Deutschland ",0,"."],"banque":["verlassen","verließ","verlässt","verlassend"]},{"enonce":"Choisis entre « inventer » et « découvrir » : complète les deux phrases.","aide":"*erfinden* crée une chose qui n’existait pas ; *entdecken* révèle une chose qui existait déjà.","type":"trous","segments":["Gutenberg hat den Buchdruck ",0,". Koch hat den Erreger der Tuberkulose ",1,"."],"banque":["gesammelt","entdeckt","erfunden","verboten"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m33"]},"explication":"La **Kernspaltung** est la fission du noyau atomique."},{"cle":{"type":"zone","ids":["m41"]},"explication":"C’est **Otto Hahn** qui reçoit seul le prix Nobel de chimie ; Lise Meitner n’est pas récompensée."},{"cle":{"type":"trous","trous":[["verlassen"]]},"affichage":"verlassen","explication":"On écrit **verlassen** : verbe de modalité (*muss*) + infinitif à la fin de la phrase."},{"cle":{"type":"trous","trous":[["erfunden"],["entdeckt"]]},"affichage":"erfunden · entdeckt","explication":"Gutenberg a **erfunden** (inventé) l’imprimerie ; Koch a **entdeckt** (découvert) un bacille qui existait déjà."}]$ex$::jsonb),
  ('df3653fa-11c0-5d35-8dbc-8b016a39d690'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le savant est-il responsable ?","competence":"argumenter","situation":"Un cours d’allemand propose un débat. Mia et Ben discutent d’un chimiste célèbre, Fritz Haber, et du rôle du savant.","documents":[{"id":"haber","type":"texte","genre":"article","titre":"Fritz Haber","blocs":["Fritz Haber entwickelt ein Verfahren zur Herstellung von Ammoniak. Daraus macht man Dünger: So kann die Landwirtschaft mehr Menschen ernähren. Haber erhält den Nobelpreis.","1915 leitet er aber auch den ersten Giftgas-Angriff bei Ypern."],"source":"Texte écrit pour l’exercice, d’après le cours"},{"id":"chat","type":"dialogue","modele":"sms","titre":"Diskussion","participants":[{"nom":"Mia","emoji":"👩","cote":"gauche"},{"nom":"Ben","emoji":"👨","cote":"droite"}],"repliques":[{"qui":"Mia","texte":"Haber hat Millionen Menschen satt gemacht!"},{"qui":"Ben","texte":"Aber sein Wissen hat auch Menschen getötet. Ist der Forscher dafür verantwortlich?"},{"qui":"Mia","texte":"Ich finde: Jeder Forscher trägt eine große Verantwortung für das, was mit seinem Wissen passiert."},{"qui":"Ben","texte":"Dann muss man das Wort „Fortschritt“ immer prüfen."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot allemand qui désigne ce que l’on fabrique avec l’ammoniac pour nourrir plus de monde.","aide":"C’est un produit que l’on répand dans les champs.","type":"zone","document":"haber","multiple":false},{"enonce":"Touche le mot allemand qui désigne la responsabilité, dans le message de Mia.","aide":"Le mot se termine par -ung et commence par *Ver-*.","type":"zone","document":"chat","multiple":false},{"enonce":"Range ces usages du savoir de Haber.","aide":"Un seul et même savoir a deux visages.","type":"categories","categories":[{"id":"c0","texte":"Un usage qui nourrit"},{"id":"c1","texte":"Un usage qui tue"}],"items":[{"id":"i0","texte":"Le gaz de combat utilisé à Ypres"},{"id":"i1","texte":"Plus de récoltes pour nourrir des milliards de personnes"},{"id":"i2","texte":"La première attaque au gaz en 1915"},{"id":"i3","texte":"L’engrais pour les champs"}]},{"enonce":"Quelle est la position de Mia dans la discussion ?","aide":"Relis son dernier message : le mot *jeder* veut dire « chaque ».","type":"choix","options":[{"id":"a","texte":"Il faut interdire toutes les recherches en chimie"},{"id":"b","texte":"Seul l’État est responsable de ce que fait un savant"},{"id":"c","texte":"Chaque chercheur est responsable de l’usage de son savoir"},{"id":"d","texte":"Le chercheur n’a aucune responsabilité après sa découverte"}],"multiple":false},{"enonce":"Relie chaque mot allemand à sa traduction.","aide":"*erfinden* = inventer ; *entdecken* = découvrir.","type":"association","gauche":[{"id":"g0","texte":"die Erfindung"},{"id":"g1","texte":"die Entdeckung"},{"id":"g2","texte":"der Fortschritt"},{"id":"g3","texte":"missbrauchen"}],"droite":[{"id":"d0","texte":"l’invention"},{"id":"d1","texte":"détourner, abuser de"},{"id":"d2","texte":"le progrès"},{"id":"d3","texte":"la découverte"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m12"]},"explication":"L’ammoniac sert à fabriquer du **Dünger**, l’engrais, qui permet de nourrir plus d’êtres humains."},{"cle":{"type":"zone","ids":["m25"]},"explication":"**die Verantwortung** : la responsabilité du chercheur est le cœur du débat."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0"}},"explication":"Le même savoir donne l’**engrais** qui nourrit et le **gaz de combat** qui tue : « Un même savoir peut nourrir ou tuer. »"},{"cle":{"type":"choix","ids":["c"]},"explication":"Mia dit que **jeder Forscher** porte une grande responsabilité pour ce qui arrive à son savoir."},{"cle":{"type":"association","paires":{"g0":"d0","g3":"d1","g2":"d2","g1":"d3"}},"explication":"**die Erfindung** = l’invention, **die Entdeckung** = la découverte, **der Fortschritt** = le progrès, **missbrauchen** = détourner."}]$ex$::jsonb),
