  ('021ade94-a51a-5a19-837e-ce13c1cb72fb'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Jardins, parcs et maisons de campagne","competence":"comprendre-langue","situation":"Lena, qui habite à Leipzig, discute avec Tom de ce que l’on fait de la nature en ville et à la campagne. Lis leur échange.","documents":[{"id":"chat","type":"dialogue","modele":"sms","titre":"Chat","participants":[{"nom":"Tom","emoji":"👦","cote":"gauche"},{"nom":"Lena","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Tom","texte":"Du fährst am Wochenende in den Schrebergarten? Wer war eigentlich Schreber?"},{"qui":"Lena","texte":"Ein Arzt, Moritz Schreber. Der erste Garten dieser Art entstand 1864 in Leipzig."},{"qui":"Tom","texte":"Und deine Oma? Sie hat doch eine kleine Hütte auf dem Land."},{"qui":"Lena","texte":"Ja, in der DDR hatten viele Familien eine Datsche. Dort wandern wir oft im Wald."}],"source":"Messages écrits pour l’exercice, d’après le cours"}],"questions":[{"enonce":"Touche le mot allemand qui désigne le métier de Moritz Schreber.","aide":"Tom demande « Wer war Schreber ? » : la réponse suit dans le message de Lena.","type":"zone","document":"chat","multiple":false},{"enonce":"Touche le mot allemand qui désigne la petite maison de campagne répandue en RDA.","aide":"La grand-mère de Lena en a une « auf dem Land », à la campagne.","type":"zone","document":"chat","multiple":false},{"enonce":"En quelle année le premier jardin de ce type naît-il à Leipzig ?","aide":"La date est dans la réponse de Lena sur Schreber.","type":"nombre"},{"enonce":"Relie chaque lieu allemand à sa définition.","aide":"*Schutz* veut dire « protection ».","type":"association","gauche":[{"id":"g0","texte":"der Schrebergarten"},{"id":"g1","texte":"der Stadtpark"},{"id":"g2","texte":"die Datsche"},{"id":"g3","texte":"das Naturschutzgebiet"}],"droite":[{"id":"d0","texte":"réserve naturelle"},{"id":"d1","texte":"petite maison de campagne"},{"id":"d2","texte":"grand parc urbain"},{"id":"d3","texte":"jardin ouvrier en location"}]}]}$ex$::jsonb,
