  ('021ade94-a51a-5a19-837e-ce13c1cb72fb'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La forêt malade et la naissance d’un parti","competence":"analyser-document","situation":"Pour comprendre comment la nature est devenue un enjeu politique, Clara croise un article sur les années 1980 et un tableau de trois moments de l’histoire de la nature.","documents":[{"id":"artikel","type":"texte","genre":"article","titre":"Der Wald in Gefahr","blocs":["In den 1980er Jahren haben viele Deutsche Angst um den Wald. Saurer Regen schadet den Bäumen: Man spricht vom Waldsterben.","Gleichzeitig protestieren viele Menschen gegen die Atomkraft. Aus diesen Bewegungen entsteht 1980 die Partei „Die Grünen“. 1983 ziehen sie zum ersten Mal in den Bundestag ein."],"source":"Article écrit pour l’exercice, d’après le cours"},{"id":"tab","type":"tableau","titre":"Was die Natur bedeutet","colonnes":["Zeit","Wer","Die Natur ist …"],"lignes":[["um 1818","Caspar David Friedrich","ein Ort für Gefühl und Mysterium"],["um 1901","Wandervogel","ein Ort der Freiheit"],["ab 1980","Die Grünen","ein politisches Thema"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice, d’après le cours"}],"questions":[{"enonce":"Touche le mot allemand qui désigne la mort des forêts due aux pluies acides.","aide":"Le mot contient *Wald* (forêt) et *sterben* (mourir).","type":"zone","document":"artikel","multiple":false},{"enonce":"Complète deux informations de l’article.","aide":"Le premier mot est une précipitation ; le second est le parlement allemand.","type":"trous","segments":["Saurer ",0," schadet den Bäumen. 1983 ziehen die Grünen in den ",1," ein."],"banque":["Bundestag","Regen","Bundesrat","Schnee"]},{"enonce":"Combien d’années s’écoulent entre la fondation des Verts et leur entrée au Bundestag ?","aide":"Les deux dates sont dans le deuxième paragraphe.","type":"nombre","unite":"ans"},{"enonce":"Touche la case du tableau qui dit ce qu’est devenue la nature à l’époque décrite dans l’article.","aide":"L’article parle des années 1980 : cherche la ligne « ab 1980 ».","type":"zone","document":"tab","multiple":false},{"enonce":"Quel changement le tableau et l’article montrent-ils ensemble ?","aide":"Compare la première et la dernière ligne du tableau.","type":"choix","options":[{"id":"a","texte":"La nature perd toute importance pour les Allemands"},{"id":"b","texte":"La nature passe du sentiment romantique à l’action politique"},{"id":"c","texte":"Les romantiques fondent le parti des Verts en 1818"},{"id":"d","texte":"La nature devient seulement un lieu de production de bois"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m19"]},"explication":"Le **Waldsterben** est la mort des forêts, causée par les pluies acides."},{"cle":{"type":"trous","trous":[["regen"],["bundestag"]]},"affichage":"Regen · Bundestag","explication":"**Saurer Regen** (pluie acide) abîme les arbres ; en 1983, les Verts entrent au **Bundestag**."},{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3 ans","explication":"1983 − 1980 = **3 ans**."},{"cle":{"type":"zone","ids":["r2c2"]},"explication":"À partir de 1980, la nature est **un sujet politique** : la peur de la mort des forêts fait naître les Verts."},{"cle":{"type":"choix","ids":["b"]},"explication":"En Allemagne, la nature est passée **du tableau au bulletin de vote** : du sentiment romantique à l’action politique."}]$ex$::jsonb),
