   $ex${"titre":"Sur la carte de l’Afrique coloniale allemande","competence":"lire-carte","situation":"Pour son dossier, Samir cherche sur une carte d’Afrique trois pays qui furent des colonies allemandes. Touche-les sur la carte.","documents":[{"id":"carte","type":"carte","titre":"Afrika heute","fond":"monde","cadrage":[-18,-36,52,16],"regionsCliquables":true,"etiquettes":[{"texte":"Afrique du Sud","lon":24,"lat":-30,"style":"pays"},{"texte":"Angola","lon":17.5,"lat":-12,"style":"pays"},{"texte":"Kenya","lon":38,"lat":0.6,"style":"pays"},{"texte":"Nigeria","lon":8,"lat":9.6,"style":"pays"},{"texte":"Gabon","lon":11.8,"lat":-0.8,"style":"pays"}],"source":"Fond de carte actuel : les pays d’aujourd’hui"}],"questions":[{"enonce":"Touche le pays qui était la colonie « Deutsch-Südwestafrika ».","aide":"C’est un pays d’Afrique australe, au bord de l’océan Atlantique, au nord de l’Afrique du Sud.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche le pays qui était la colonie « Deutsch-Ostafrika ».","aide":"Il est situé sur la côte de l’océan Indien, au sud du Kenya.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche le Cameroun, une autre colonie allemande, sur le golfe de Guinée.","aide":"Il se trouve à l’angle du golfe de Guinée, entre le Nigeria et le Gabon.","type":"zone","document":"carte","multiple":false},{"enonce":"Range ces repères du plus ancien au plus récent. Le premier est « Conférence de Berlin ».","aide":"Les dates sont 1884-1885, 1897, 1919 et 2021.","type":"ordre","items":[{"id":"a","texte":"Conférence de Berlin"},{"id":"b","texte":"Reconnaissance du génocide par l’Allemagne"},{"id":"c","texte":"Traité de Versailles : fin des colonies"},{"id":"d","texte":"Une place au soleil réclamée par von Bülow"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["NAM"]},"explication":"Le **Deutsch-Südwestafrika** correspond à l’actuelle **Namibie**, où a eu lieu le massacre des Herero et des Nama."},{"cle":{"type":"zone","ids":["TZA"]},"explication":"Le **Deutsch-Ostafrika** correspond à l’actuelle **Tanzanie**."},{"cle":{"type":"zone","ids":["CMR"]},"explication":"Le **Cameroun** fut une colonie allemande jusqu’en 1919."},{"cle":{"type":"ordre","ids":["a","d","c","b"]},"explication":"**1884-1885** → **1897** → **1919** → **2021**."}]$ex$::jsonb),
  ('61d7abb4-9780-51e0-9e71-37925864d94e'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une lettre de Philadelphie","competence":"comprendre-langue","situation":"Anna a quitté l’Allemagne au XIXe siècle. Sa lettre (imaginée) à sa mère raconte son nouveau pays. Lis-la.","documents":[{"id":"brief","type":"texte","genre":"lettre","titre":"Philadelphia, den 12. Mai 1883","blocs":["Liebe Mutter, ich bin gut in Amerika angekommen. Zu Hause gab es keine Arbeit, deshalb bin ich ausgewandert.","Ich wohne jetzt in der Nähe von Germantown. Die Stadt gibt es schon seit 1683, und viele Nachbarn sprechen Deutsch.","Meine Cousine ist auch hier: Sie ist letztes Jahr eingewandert. Schreib mir bald!"],"source":"Lettre imaginée pour l’exercice, d’après le cours"}],"questions":[{"enonce":"Touche le nom de la ville fondée par des Allemands en Pennsylvanie en 1683.","aide":"Le nom contient *German* : c’est la ville des Allemands.","type":"zone","document":"brief","multiple":false},{"enonce":"Combien d’années séparent la fondation de Germantown de la date de la lettre d’Anna ?","aide":"La date de la lettre est dans le titre du document.","type":"nombre","unite":"ans"},{"enonce":"Touche le verbe qui dit qu’Anna a quitté son pays.","aide":"Il commence par *aus-* : vers l’extérieur.","type":"zone","document":"brief","multiple":false},{"enonce":"Complète les deux phrases avec le bon participe.","aide":"Une personne quitte un pays, l’autre y entre : pense à *vers l’extérieur* et *vers l’intérieur*.","type":"trous","segments":["Anna hat Deutschland verlassen : sie ist ",0,". Ihre Cousine ist neu in Amerika angekommen : sie ist ",1,"."],"banque":["ausgewandert","eingewandert","zurückgekommen","ausgestiegen"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m25"]},"explication":"**Germantown**, fondée en 1683 en Pennsylvanie, est un symbole de l’émigration allemande."},{"cle":{"type":"nombre","valeur":200,"tolerance":0},"affichage":"200 ans","explication":"1883 − 1683 = **200 ans**."},{"cle":{"type":"zone","ids":["m17"]},"explication":"**ausgewandert** : *aus-* indique la sortie, Anna a émigré."},{"cle":{"type":"trous","trous":[["ausgewandert"],["eingewandert"]]},"affichage":"ausgewandert · eingewandert","explication":"**ausgewandert** = émigrée (elle quitte l’Allemagne) ; **eingewandert** = immigrée (elle arrive aux États-Unis)."}]$ex$::jsonb),
  ('61d7abb4-9780-51e0-9e71-37925864d94e'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Puissance discrète, puissance assumée","competence":"analyser-document","situation":"Pour comprendre l’influence de l’Allemagne dans le monde, Yanis croise un tableau sur son rayonnement culturel et un texte sur sa politique étrangère.","documents":[{"id":"soft","type":"tableau","titre":"Deutsche Soft Power","colonnes":["Instrument","Was er macht"],"lignes":[["Das Goethe-Institut","verbreitet Sprache und Kultur, mehr als 150 Institute weltweit"],["Die Deutsche Welle","sendet Radio und Fernsehen in etwa 30 Sprachen"],["Made in Germany","Autos und Maschinen mit gutem Ruf"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice, d’après le cours"},{"id":"politik","type":"texte","genre":"article","titre":"Außenpolitik","blocs":["Nach 1945 setzt die Bundesrepublik auf den Westen. Später setzt Willy Brandt auf die Entspannung mit dem Osten: Man nennt das Ostpolitik.","Die Bundeswehr ist erst seit den 1990er Jahren im Ausland im Einsatz.","Im Februar 2022 spricht Bundeskanzler Olaf Scholz nach dem Angriff auf die Ukraine von einer Zeitenwende."],"source":"Texte écrit pour l’exercice, d’après le cours"}],"questions":[{"enonce":"Touche la case qui dit en combien de langues environ émet la Deutsche Welle.","aide":"Cherche la ligne « Die Deutsche Welle ».","type":"zone","document":"soft","multiple":false},{"enonce":"Touche le mot par lequel Olaf Scholz parle d’un « changement d’époque ».","aide":"Le mot est composé de *Zeit* (temps, époque) et d’un nom qui veut dire « tournant ».","type":"zone","document":"politik","multiple":false},{"enonce":"Range ces moments de la politique étrangère dans l’ordre chronologique. Le premier est « Ostpolitik ».","aide":"Brandt est chancelier dans les années 1970 ; le texte donne les deux autres repères.","type":"ordre","items":[{"id":"a","texte":"Zeitenwende"},{"id":"b","texte":"Bundeswehr im Ausland"},{"id":"c","texte":"Ostpolitik"}]},{"enonce":"Complète la phrase avec la bonne préposition.","aide":"*der Einfluss* se construit avec une préposition suivie de l’accusatif.","type":"trous","segments":["Der Einfluss ",0," andere Länder wächst."],"banque":["von","auf","zu","bei"]},{"enonce":"Parmi ces outils, lequel relève du rayonnement culturel plutôt que de la diplomatie ?","aide":"Le tableau parle de langue et de culture, le texte de politique étrangère.","type":"choix","options":[{"id":"a","texte":"L’Ostpolitik de Willy Brandt"},{"id":"b","texte":"La Bundeswehr à l’étranger"},{"id":"c","texte":"La Zeitenwende de Scholz"},{"id":"d","texte":"Le Goethe-Institut"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"La Deutsche Welle émet en **une trentaine de langues**."},{"cle":{"type":"zone","ids":["m49"]},"explication":"**Zeitenwende** : le « changement d’époque » annoncé en février 2022."},{"cle":{"type":"ordre","ids":["c","b","a"]},"explication":"**Ostpolitik** (Brandt) → **années 1990** (premiers engagements de la Bundeswehr à l’étranger) → **2022** (Zeitenwende)."},{"cle":{"type":"trous","trous":[["auf"]]},"affichage":"auf","explication":"**der Einfluss auf + accusatif** : l’influence sur quelqu’un ou quelque chose."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le **Goethe-Institut** fait connaître la langue et la culture allemandes : c’est du *soft power*."}]$ex$::jsonb),
  ('01dddb98-7603-54fe-b7ea-f3f66e908200'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le train était déjà parti","competence":"manier-langue","situation":"Tim a raté son train hier. Il raconte sa soirée à Lena par messages. Lis leur conversation.","documents":[{"id":"chat","type":"dialogue","modele":"sms","titre":"Nachrichten","participants":[{"nom":"Lena","emoji":"👧","cote":"gauche"},{"nom":"Tim","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lena","texte":"Wo warst du gestern? Ich habe dich gesucht."},{"qui":"Tim","texte":"Als ich am Bahnhof ankam, war der Zug schon abgefahren. Danach bin ich nach Hause gefahren."},{"qui":"Lena","texte":"Oje, du Armer!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les deux mots qui forment le plus-que-parfait dans le message de Tim.","aide":"Le plus-que-parfait se forme avec le prétérit de *sein* (ou *haben*) et un participe II.","type":"zone","document":"chat","multiple":true},{"enonce":"Complète la phrase avec l’auxiliaire qui convient.","aide":"*essen* se conjugue avec *haben* ; la principale est au prétérit.","type":"trous","segments":["Nachdem er gegessen ",0,", ging er schlafen."],"banque":["war","hat","wurde","hatte"]},{"enonce":"Relie chaque parfait à son plus-que-parfait.","aide":"On remplace l’auxiliaire du parfait par son prétérit, le participe ne change pas.","type":"association","gauche":[{"id":"g0","texte":"ich habe gegessen"},{"id":"g1","texte":"er ist gegangen"},{"id":"g2","texte":"wir haben gewartet"},{"id":"g3","texte":"sie hat gelacht"}],"droite":[{"id":"d0","texte":"ich hatte gegessen"},{"id":"d1","texte":"er war gegangen"},{"id":"d2","texte":"sie hatte gelacht"},{"id":"d3","texte":"wir hatten gewartet"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m13","m17"]},"explication":"**war … abgefahren** : prétérit de *sein* + participe II. Ce temps dit que le départ du train est **antérieur** à l’arrivée de Tim."},{"cle":{"type":"trous","trous":[["hatte"]]},"affichage":"hatte","explication":"**hatte** : *nachdem* demande un plus-que-parfait quand la principale est au prétérit (« ging »)."},{"cle":{"type":"association","paires":{"g0":"d0","g1":"d1","g3":"d2","g2":"d3"}},"explication":"Le plus-que-parfait garde le **même auxiliaire** et le même participe II que le parfait, mais l’auxiliaire passe au prétérit."}]$ex$::jsonb),
  ('01dddb98-7603-54fe-b7ea-f3f66e908200'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une journée de classe à Cologne","competence":"manier-langue","situation":"La classe de Jonas passe la journée à Cologne. Voici le programme affiché dans le couloir. Utilise-le pour construire des phrases sur l’ordre des événements.","documents":[{"id":"plan","type":"fiche","modele":"horaires","entete":"Klassenfahrt nach Köln","sousTitre":"Programm","emoji":"🚆","teinte":"bleu","lignes":[{"texte":"Dom besuchen","valeur":"9:00","id":"z1"},{"texte":"Spaziergang am Rhein","valeur":"11:00","id":"z2"},{"texte":"Mittagessen im Café","valeur":"12:30","id":"z3"},{"texte":"Museum","valeur":"14:00","id":"z4"}],"pied":"Treffpunkt: Hauptbahnhof","source":"Programme écrit pour l’exercice"}],"questions":[{"enonce":"Touche l’activité qui a lieu juste avant le déjeuner au café.","aide":"Lis les horaires dans l’ordre : le déjeuner est à 12 h 30.","type":"zone","document":"plan","multiple":false},{"enonce":"Remets ces groupes dans l’ordre pour dire : « Après avoir visité la cathédrale, la classe est allée au bord du Rhin. » Le premier groupe est « Nachdem die Klasse ».","aide":"Dans la subordonnée en *nachdem*, le verbe conjugué est en dernière position ; la principale commence par son verbe.","type":"ordre","items":[{"id":"a","texte":"Nachdem die Klasse"},{"id":"b","texte":"den Dom"},{"id":"c","texte":"ging sie zum Rhein"},{"id":"d","texte":"besucht hatte,"}]},{"enonce":"Complète la phrase : « Après avoir déjeuné, nous sommes allés au musée. »","aide":"Le sujet est *wir* : l’auxiliaire est au prétérit pluriel, à la fin de la subordonnée.","type":"trous","segments":["Nachdem wir zu Mittag ",0," ",1,", gingen wir ins Museum."],"banque":["gegessen","haben","hatten","hatte"]},{"enonce":"Quelle phrase respecte le décalage des temps après *nachdem* ?","aide":"La subordonnée doit être « un cran plus loin dans le passé » que la principale.","type":"choix","options":[{"id":"a","texte":"Nachdem er hatte gegessen, ging er schlafen."},{"id":"b","texte":"Nachdem er aß, ging er schlafen."},{"id":"c","texte":"Nachdem er gegessen hatte, ging er schlafen."},{"id":"d","texte":"Nachdem er gegessen hat, ging er schlafen."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"La promenade au bord du Rhin (**Spaziergang am Rhein**, 11 h) précède le déjeuner de 12 h 30."},{"cle":{"type":"ordre","ids":["a","b","d","c"]},"explication":"**Nachdem die Klasse den Dom besucht hatte, ging sie zum Rhein.** Plus-que-parfait dans la subordonnée, prétérit dans la principale."},{"cle":{"type":"trous","trous":[["gegessen"],["hatten"]]},"affichage":"gegessen · hatten","explication":"**gegessen hatten** : participe II puis auxiliaire au prétérit. Avec « haben », il n’y aurait pas de décalage avec *gingen*."},{"cle":{"type":"choix","ids":["c"]},"explication":"Avec une principale au prétérit, la subordonnée en *nachdem* est au **plus-que-parfait**, et le verbe conjugué est à la fin."}]$ex$::jsonb),
  ('01dddb98-7603-54fe-b7ea-f3f66e908200'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Max rate son train","competence":"manier-langue","situation":"Max a raconté sa journée de samedi dans un petit récit. Un tableau rappelle les mots de l’avant et de l’après.","documents":[{"id":"geschichte","type":"texte","genre":"recit","titre":"Ein verpasster Zug","blocs":["Letzten Samstag wollte Max nach Berlin fahren. Als er am Bahnhof ankam, war der Zug schon abgefahren. Er hatte zu lange gefrühstückt.","Bevor er nach Hause ging, kaufte er einen Kaffee. Nachdem er zu Hause angekommen war, rief er seine Freundin an."],"source":"Récit écrit pour l’exercice"},{"id":"tab","type":"tableau","titre":"Vorher und nachher","colonnes":["Nature","Avant","Après"],"lignes":[["Subordonnant","bevor","nachdem"],["Adverbe","vorher","nachher, danach"],["Préposition + datif","vor dem Essen","nach dem Essen"]],"enteteLignes":true,"source":"Tableau tiré du cours"}],"questions":[{"enonce":"Touche le subordonnant qui veut dire « avant que / avant de » et qui garde le même temps que la principale.","aide":"Il est en début du deuxième paragraphe ; le tableau le range dans la colonne « Avant ».","type":"zone","document":"geschichte","multiple":false},{"enonce":"Remets les actions de Max dans l’ordre chronologique. La première est « Max kommt am Bahnhof an ».","aide":"Pense à *bevor* (avant de rentrer) et à *nachdem* (après être arrivé).","type":"ordre","items":[{"id":"a","texte":"Max ruft seine Freundin an"},{"id":"b","texte":"Max kauft einen Kaffee"},{"id":"c","texte":"Max kommt zu Hause an"},{"id":"d","texte":"Max kommt am Bahnhof an"}]},{"enonce":"Range ces mots dans la bonne colonne, avec l’aide du tableau.","aide":"*vor* signifie « avant », *nach* signifie « après ».","type":"categories","categories":[{"id":"c0","texte":"Antériorité (avant)"},{"id":"c1","texte":"Postériorité (après)"}],"items":[{"id":"i0","texte":"nach dem Essen"},{"id":"i1","texte":"vorher"},{"id":"i2","texte":"vor dem Essen"},{"id":"i3","texte":"danach"},{"id":"i4","texte":"bevor"},{"id":"i5","texte":"nachdem"}]},{"enonce":"Complète la phrase : « Après avoir fait mes devoirs, je vais au cinéma. »","aide":"La principale est au présent : la subordonnée est au parfait.","type":"trous","segments":["Nachdem ich die Hausaufgaben gemacht ",0,", gehe ich ins Kino."],"banque":["hatte","machte","bin","habe"]},{"enonce":"Comment dit-on : « Avant de partir, il ferme la fenêtre » ?","aide":"*bevor* garde le même temps que la principale et se construit avec un verbe conjugué.","type":"choix","options":[{"id":"a","texte":"Vor zu gehen, schließt er das Fenster."},{"id":"b","texte":"Bevor er ging, schließt er das Fenster."},{"id":"c","texte":"Bevor er geht, schließt er das Fenster."},{"id":"d","texte":"Nachdem er geht, schließt er das Fenster."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m22"]},"explication":"**Bevor** : l’antériorité s’exprime sans décalage des temps (*Bevor er nach Hause ging, kaufte er…*)."},{"cle":{"type":"ordre","ids":["d","b","c","a"]},"explication":"Gare → **café acheté** (*bevor er nach Hause ging*) → arrivée à la maison → **coup de téléphone** (*nachdem er angekommen war*)."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1","i4":"c0","i5":"c1"}},"explication":"**vorher, bevor, vor dem Essen** disent l’antériorité ; **nachdem, danach, nach dem Essen** disent la postériorité."},{"cle":{"type":"trous","trous":[["habe"]]},"affichage":"habe","explication":"**habe** : avec une principale au présent, la subordonnée en *nachdem* est au **parfait** (*gemacht habe*)."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Bevor er geht, schließt er das Fenster.** *bevor* + verbe conjugué, jamais « vor … zu »."}]$ex$::jsonb),
  ('942a29d1-ac6a-58ba-87c7-998d96d44a00'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Un coup de main avant le contrôle","competence":"manier-langue","situation":"Jana et Paul se préparent pour le contrôle d’allemand. Lis leur échange, puis observe quels verbes demandent le datif.","documents":[{"id":"chat","type":"dialogue","modele":"sms","titre":"Nachrichten","participants":[{"nom":"Jana","emoji":"👧","cote":"gauche"},{"nom":"Paul","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Jana","texte":"Kannst du mir bitte helfen? Ich verstehe die Aufgabe nicht."},{"qui":"Paul","texte":"Klar! Ich rufe dich gleich an."},{"qui":"Jana","texte":"Danke!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le pronom au datif qui complète le verbe « helfen ».","aide":"En français, « aider quelqu’un » a un COD ; en allemand, *helfen* se construit autrement.","type":"zone","document":"chat","multiple":false},{"enonce":"Touche le pronom à l’accusatif qui complète le verbe « anrufen ».","aide":"Ici, c’est l’inverse : le français dit « téléphoner à », mais l’allemand emploie le cas du COD.","type":"zone","document":"chat","multiple":false},{"enonce":"Complète la phrase de politesse.","aide":"*danken* est un verbe à datif ; on vouvoie la personne.","type":"trous","segments":["Ich danke ",0," für die Einladung."],"banque":["Sie","Ihnen","Ihren","Ihr"]},{"enonce":"Range chaque verbe selon le cas de son complément de personne.","aide":"Les verbes à retenir pour le datif : *helfen, danken, folgen, gefallen, gehören*.","type":"categories","categories":[{"id":"c0","texte":"Datif"},{"id":"c1","texte":"Accusatif"}],"items":[{"id":"i0","texte":"gehören"},{"id":"i1","texte":"anrufen"},{"id":"i2","texte":"fragen"},{"id":"i3","texte":"helfen"},{"id":"i4","texte":"bitten (jn um etwas)"},{"id":"i5","texte":"danken"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2"]},"explication":"*helfen* demande le **datif** : *Kannst du **mir** helfen ?* (et non *mich*)."},{"cle":{"type":"zone","ids":["m13"]},"explication":"*jn anrufen* demande l’**accusatif** : *Ich rufe **dich** an.*"},{"cle":{"type":"trous","trous":[["ihnen"]]},"affichage":"Ihnen","explication":"**Ihnen** est le datif de la forme de politesse *Sie* : *Ich danke Ihnen.*"},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0","i4":"c1","i5":"c0"}},"explication":"**Datif** : helfen, danken, gehören. **Accusatif** : fragen, anrufen, bitten (la personne, avec *um* pour la chose)."}]$ex$::jsonb),
  ('942a29d1-ac6a-58ba-87c7-998d96d44a00'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Un mot de remerciement","competence":"manier-langue","situation":"Jonas écrit à Mme Keller, qui l’a invité à une conférence. Lis son message et repère les cas.","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"Eine Nachricht an Frau Keller","blocs":["Liebe Frau Keller,","ich danke Ihnen für die Einladung. Mein Bruder hilft mir bei der Planung. Ich frage den Direktor nach dem Termin.","Das Buch gehört meiner Schwester; sie bringt es morgen mit. Mit freundlichen Grüßen, Jonas"],"source":"Message écrit pour l’exercice"}],"questions":[{"enonce":"Touche le pronom au datif qui complète le verbe « danken ».","aide":"C’est la forme de politesse, avec un I majuscule.","type":"zone","document":"mail","multiple":false},{"enonce":"Touche le nom de la personne à qui Jonas pose une question (verbe « fragen »).","aide":"Ce nom désigne le chef d’un établissement.","type":"zone","document":"mail","multiple":false},{"enonce":"Complète avec le bon article ou adjectif possessif.","aide":"*helfen* demande le datif féminin ; *fragen* demande l’accusatif masculin.","type":"trous","segments":["Ich helfe ",0," Schwester und frage ",1," Lehrer."],"banque":["meine","dem","den","meiner"]},{"enonce":"Remplace « dem Schüler die Regel » par des pronoms : « Ich erkläre sie ihm. » Remets les mots dans l’ordre ; le premier est « Ich ».","aide":"Avec deux pronoms, l’accusatif (la chose) vient avant le datif (la personne).","type":"ordre","items":[{"id":"a","texte":"ihm"},{"id":"b","texte":"sie"},{"id":"c","texte":"erkläre"},{"id":"d","texte":"Ich"}]},{"enonce":"Relie chaque verbe allemand à son sens.","aide":"Ces quatre verbes se construisent avec le datif.","type":"association","gauche":[{"id":"g0","texte":"widersprechen"},{"id":"g1","texte":"begegnen"},{"id":"g2","texte":"zuhören"},{"id":"g3","texte":"gratulieren"}],"droite":[{"id":"d0","texte":"écouter quelqu’un"},{"id":"d1","texte":"contredire"},{"id":"d2","texte":"féliciter"},{"id":"d3","texte":"rencontrer par 