   $ex${"titre":"Partir, arriver, changer : les préverbes","competence":"comprendre-langue","situation":"Pour comprendre des verbes qu’il ne connaît pas, Elias lit un tableau de quatre préverbes séparables.","documents":[{"id":"tab","type":"tableau","titre":"Trennbare Vorsilben","colonnes":["Préverbe","Idée","Verbe"],"lignes":[["aus-","vers l’extérieur","auswandern"],["ein-","vers l’intérieur","einwandern"],["um-","changement","umziehen"],["zurück-","retour","zurückkommen"]],"enteteLignes":true,"source":"Tableau tiré du cours"}],"questions":[{"enonce":"Touche le préverbe qui exprime le retour, le mouvement en arrière.","aide":"Cherche la colonne « Idée » et la ligne qui parle de retour.","type":"zone","document":"tab","multiple":false},{"enonce":"Relie chaque verbe à son sens.","aide":"Additionne l’idée du préverbe et le sens du radical.","type":"association","gauche":[{"id":"g0","texte":"auswandern"},{"id":"g1","texte":"einwandern"},{"id":"g2","texte":"umziehen"},{"id":"g3","texte":"zurückkommen"}],"droite":[{"id":"d0","texte":"revenir"},{"id":"d1","texte":"immigrer"},{"id":"d2","texte":"déménager"},{"id":"d3","texte":"émigrer"}]},{"enonce":"Complète la phrase avec le bon préverbe.","aide":"Quitter un pays, c’est aller vers l’extérieur.","type":"trous","segments":["Sie verlässt Deutschland : sie wandert ",0,"."],"banque":["um","zurück","ein","aus"]}]}$ex$::jsonb,
