  ('fa17180e-43d2-5982-b445-9009ece3f398'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une ville qui change","competence":"analyser-texte","situation":"Pour son exposé sur l’histoire de sa ville, Lina lit un petit texte plein de verbes à préverbe.","documents":[{"id":"stadt","type":"texte","genre":"article","titre":"Eine Stadt im Wandel","blocs":["Nach dem Krieg war die Stadt fast ganz zerstört. Viele Familien sind weggegangen, aber neue Bewohner sind eingewandert.","Man hat die Häuser erneuert, und die Stadt hat sich stark verändert. Die neue Brücke erleichtert den Weg zur Schule."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche le participe qui dit que la ville a été détruite en morceaux.","aide":"Le préverbe *zer-* exprime une destruction en morceaux.","type":"zone","document":"stadt","multiple":false},{"enonce":"Complète la phrase du texte.","aide":"Le verbe a un préverbe inséparable : son participe n’a pas de *ge-*.","type":"trous","segments":["Die Stadt hat sich stark ",0,"."],"banque":["verändern","veränderte","geverändert","verändert"]},{"enonce":"Range chaque verbe : le préverbe est-il séparable ou inséparable ?","aide":"Les préverbes inséparables sont *be-, er-, ver-, ent-, zer-, miss-*.","type":"categories","categories":[{"id":"c0","texte":"Séparable"},{"id":"c1","texte":"Inséparable"}],"items":[{"id":"i0","texte":"zurückkommen"},{"id":"i1","texte":"zerbrechen"},{"id":"i2","texte":"umdenken"},{"id":"i3","texte":"erreichen"},{"id":"i4","texte":"aussteigen"},{"id":"i5","texte":"verändern"}]},{"enonce":"Dans le texte, que veut dire « erleichtern » (de *leicht*) ?","aide":"*er-* rend, souvent à partir d’un adjectif : *leicht* = léger, facile.","type":"choix","options":[{"id":"a","texte":"alourdir"},{"id":"b","texte":"réparer"},{"id":"c","texte":"interdire"},{"id":"d","texte":"faciliter"}],"multiple":false}]}$ex$::jsonb,
