  ('fa17180e-43d2-5982-b445-9009ece3f398'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Verschlafen, verlaufen, verschrieben","competence":"comprendre-langue","situation":"Mia raconte à Ben une matinée catastrophique. Utilise la méthode du cours pour comprendre ses verbes, puis range-les.","documents":[{"id":"chat","type":"dialogue","modele":"sms","titre":"Nachrichten","participants":[{"nom":"Mia","emoji":"👧","cote":"gauche"},{"nom":"Ben","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mia","texte":"Heute Morgen habe ich verschlafen, und dann habe ich mich auf dem Weg zur Schule auch noch verlaufen!"},{"qui":"Ben","texte":"Oje. Hast du wenigstens dein Heft mitgebracht?"},{"qui":"Mia","texte":"Ja. Aber beim Schreiben habe ich mich zweimal verschrieben."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le verbe qui veut dire « dormir trop longtemps ».","aide":"Il est dans le premier message de Mia ; *schlafen* signifie « dormir ».","type":"zone","document":"chat","multiple":false},{"enonce":"Range ces verbes en *ver-* selon la valeur du préverbe.","aide":"Pour chaque verbe, demande-toi : est-ce que quelque chose change, se trompe ou s’épuise ?","type":"categories","categories":[{"id":"c0","texte":"Transformation"},{"id":"c1","texte":"Erreur"},{"id":"c2","texte":"Consommation complète"}],"items":[{"id":"i0","texte":"sich verlaufen"},{"id":"i1","texte":"verbrauchen"},{"id":"i2","texte":"sich verschreiben"},{"id":"i3","texte":"verändern"},{"id":"i4","texte":"verbessern (de besser)"},{"id":"i5","texte":"verschlafen"}]},{"enonce":"Complète la phrase.","aide":"Après *hat*, il faut un participe II ; *ver-* est inséparable.","type":"trous","segments":["Er hat sich im Wald ",0,"."],"banque":["geverlaufen","verlaufen","verlaufend","verläuft"]},{"enonce":"Quel est le participe II de « zerstören » ?","aide":"*zer-* est un préverbe inséparable.","type":"choix","options":[{"id":"a","texte":"zerstört"},{"id":"b","texte":"zugestört"},{"id":"c","texte":"gezerstört"},{"id":"d","texte":"zerstörend"}],"multiple":false},{"enonce":"Relie chaque verbe séparable à son sens.","aide":"*mit-* = avec ; *weg-* = au loin ; *auf-* = ouverture ; *an-* = contact.","type":"association","gauche":[{"id":"g0","texte":"mitbringen"},{"id":"g1","texte":"wegwerfen"},{"id":"g2","texte":"aufmachen"},{"id":"g3","texte":"ankommen"}],"droite":[{"id":"d0","texte":"apporter"},{"id":"d1","texte":"arriver"},{"id":"d2","texte":"jeter"},{"id":"d3","texte":"ouvrir"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4"]},"explication":"**verschlafen** : *ver-* exprime ici l’erreur, le « raté » : dormir plus que prévu."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c2","i2":"c1","i3":"c0","i4":"c0","i5":"c1"}},"explication":"**Transformation** : verbessern, verändern. **Erreur** : sich verschreiben, verschlafen, sich verlaufen. **Consommation complète** : verbrauchen."},{"cle":{"type":"trous","trous":[["verlaufen"]]},"affichage":"verlaufen","explication":"**verlaufen** : participe II de *sich verlaufen* (se perdre), sans *ge-*."},{"cle":{"type":"choix","ids":["a"]},"explication":"**zerstört** : un préverbe inséparable ne prend pas *ge-*."},{"cle":{"type":"association","paires":{"g0":"d0","g3":"d1","g1":"d2","g2":"d3"}},"explication":"**mitbringen** = apporter, **wegwerfen** = jeter, **aufmachen** = ouvrir, **ankommen** = arriver."}]$ex$::jsonb),
  ('22a70af2-3b16-57ba-9179-a8946666b8e3'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Cuisiner en musique","competence":"manier-langue","situation":"Emma demande à Tim ce qu’il fait. Il lui répond par message : plusieurs choses se passent en même temps.","documents":[{"id":"chat","type":"dialogue","modele":"sms","titre":"Nachrichten","participants":[{"nom":"Emma","emoji":"👧","cote":"gauche"},{"nom":"Tim","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Emma","texte":"Was machst du gerade?"},{"qui":"Tim","texte":"Ich koche, und währenddessen höre ich Musik. Beim Essen sehen wir dann fern."},{"qui":"Emma","texte":"Schön! Ich lese."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche l’adverbe qui veut dire « pendant ce temps ».","aide":"C’est un adverbe : le verbe vient juste après lui (inversion).","type":"zone","document":"chat","multiple":false},{"enonce":"Complète la phrase : « Pendant que je travaille, il dort. »","aide":"Le subordonnant exprime que les deux actions se passent en même temps.","type":"trous","segments":[0," ich arbeite, schläft er."],"banque":["Damit","Ob","Während","Dass"]},{"enonce":"Relie chaque construction à sa traduction.","aide":"*beim* + infinitif substantivé traduit le gérondif français.","type":"association","gauche":[{"id":"g0","texte":"beim Essen"},{"id":"g1","texte":"beim Lesen"},{"id":"g2","texte":"beim Autofahren"},{"id":"g3","texte":"solange es regnet"}],"droite":[{"id":"d0","texte":"tant qu’il pleut"},{"id":"d1","texte":"en conduisant"},{"id":"d2","texte":"en mangeant"},{"id":"d3","texte":"en lisant"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7"]},"explication":"**währenddessen** : « pendant ce temps », adverbe suivi de l’inversion (*höre ich*)."},{"cle":{"type":"trous","trous":[["wahrend"]]},"affichage":"Während","explication":"**Während** + verbe à la fin (*arbeite*), puis principale avec son verbe en tête (*schläft er*)."},{"cle":{"type":"association","paires":{"g3":"d0","g2":"d1","g0":"d2","g1":"d3"}},"explication":"**beim Essen**, **beim Lesen**, **beim Autofahren** rendent « en + participe présent » ; **solange** = tant que."}]$ex$::jsonb),
  ('22a70af2-3b16-57ba-9179-a8946666b8e3'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un samedi chez les Schmidt","competence":"analyser-texte","situation":"Un samedi de pluie, la famille Schmidt se partage les tâches. Lis le récit puis range les façons de dire « en même temps ».","documents":[{"id":"samstag","type":"texte","genre":"recit","titre":"Ein Samstag bei Familie Schmidt","blocs":["Während der Vater kocht, deckt die Tochter den Tisch. Beim Essen sprechen alle über die Woche.","Solange es regnet, bleibt die Familie zu Hause. Gleichzeitig spielt der Sohn leise Gitarre."],"source":"Récit écrit pour l’exercice"}],"questions":[{"enonce":"Touche l’adverbe qui veut dire « au même moment » et qui provoque l’inversion.","aide":"Le sujet « der Sohn » vient après le verbe.","type":"zone","document":"samstag","multiple":false},{"enonce":"Range chaque expression selon sa construction.","aide":"Regarde si l’expression contient un verbe conjugué et où il se trouve.","type":"categories","categories":[{"id":"c0","texte":"Subordonnant (verbe à la fin)"},{"id":"c1","texte":"Adverbe (inversion)"},{"id":"c2","texte":"Nom ou préposition (pas de verbe conjugué)"}],"items":[{"id":"i0","texte":"Währenddessen sieht sie fern"},{"id":"i1","texte":"Während der Vater kocht"},{"id":"i2","texte":"Beim Essen"},{"id":"i3","texte":"Gleichzeitig spielt der Sohn"},{"id":"i4","texte":"Während des Unterrichts"},{"id":"i5","texte":"Solange es regnet"}]},{"enonce":"Complète la phrase : « Chaque fois que je le vois, il rit. »","aide":"La phrase est au présent et la situation se répète.","type":"trous","segments":["Immer ",0," ich ihn sehe, lacht er."],"banque":["dass","wenn","als","ob"]},{"enonce":"Remets les mots dans l’ordre : « Au repas, nous écoutons la radio. » Le premier groupe est « Beim Essen ».","aide":"Après le groupe de tête, le verbe conjugué vient en deuxième position.","type":"ordre","items":[{"id":"a","texte":"Beim Essen"},{"id":"b","texte":"hören"},{"id":"c","texte":"Radio"},{"id":"d","texte":"wir"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m24"]},"explication":"**Gleichzeitig** : adverbe, donc verbe en 2e position (*spielt der Sohn*)."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c2","i3":"c1","i4":"c2","i5":"c0"}},"explication":"**Subordonnants** : *während, solange* (verbe à la fin). **Adverbes** : *gleichzeitig, währenddessen* (inversion). **Sans verbe conjugué** : *beim Essen, während des Unterrichts*."},{"cle":{"type":"trous","trous":[["wenn"]]},"affichage":"wenn","explication":"**wenn** : « chaque fois », ou présent et futur ; *als* est réservé à un moment unique du passé."},{"cle":{"type":"ordre","ids":["a","b","d","c"]},"explication":"**Beim Essen hören wir Radio.** Le groupe de tête occupe la première place, le verbe la deuxième, puis le sujet."}]$ex$::jsonb),
  ('22a70af2-3b16-57ba-9179-a8946666b8e3'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Deux actions, un même moment","competence":"manier-langue","situation":"Pour réviser, Léa a recopié quelques phrases avec « während » et un tableau des outils de la simultanéité. Croise-les.","documents":[{"id":"saetze","type":"texte","genre":"recit","titre":"Vier Sätze","blocs":["Während Paul Sport liebt, liest seine Schwester lieber.","Während er kocht, deckt sie den Tisch.","Während die Stadt wächst, schrumpft das Dorf.","Während sie kocht, singt er."],"source":"Phrases écrites pour l’exercice"},{"id":"tab","type":"tableau","titre":"Werkzeuge der Gleichzeitigkeit","colonnes":["Outil","Nature","Construction"],"lignes":[["während","subordonnant","verbe à la fin"],["während + génitif","préposition","groupe nominal"],["beim + infinitif","préposition + nom","pas de verbe conjugué"],["gleichzeitig","adverbe","inversion"],["solange","subordonnant","verbe à la fin"]],"enteteLignes":true,"source":"Tableau tiré du cours"}],"questions":[{"enonce":"Touche la case qui dit quelle construction suit l’adverbe « gleichzeitig ».","aide":"Cherche la ligne « gleichzeitig », colonne « Construction ».","type":"zone","document":"tab","multiple":false},{"enonce":"Dans les quatre phrases, « während » a-t-il un sens temporel (pendant que) ou adversatif (tandis que) ?","aide":"Si les deux actions s’opposent, c’est adversatif ; si elles se déroulent ensemble, c’est temporel.","type":"categories","categories":[{"id":"c0","texte":"Temporel : pendant que"},{"id":"c1","texte":"Adversatif : tandis que"}],"items":[{"id":"i0","texte":"Während er kocht, deckt sie den Tisch."},{"id":"i1","texte":"Während Paul Sport liebt, liest seine Schwester lieber."},{"id":"i2","texte":"Während die Stadt wächst, schrumpft das Dorf."},{"id":"i3","texte":"Während sie kocht, singt er."}]},{"enonce":"Remets ces groupes dans l’ordre : « En faisant ses devoirs, il écoute de la musique ; pendant ce temps, sa sœur regarde la télévision. » Le premier groupe est « Bei den Hausaufgaben ».","aide":"Chaque proposition commence par un groupe de tête, puis le verbe conjugué en deuxième position.","type":"ordre","items":[{"id":"a","texte":"Musik;"},{"id":"b","texte":"hört"},{"id":"c","texte":"er"},{"id":"d","texte":"sieht"},{"id":"e","texte":"seine Schwester fern"},{"id":"f","texte":"währenddessen"},{"id":"g","texte":"Bei den Hausaufgaben"}]},{"enonce":"Complète avec la forme exacte de l’article.","aide":"*während*, préposition, est suivie du génitif ; *Unterricht* est masculin.","type":"trous","segments":["Während ",0," Unterrichts ist das Handy aus."],"banque":["den","des","der","dem"]},{"enonce":"Comment dit-on « En lisant, j’écoute de la musique » ?","aide":"L’infinitif devient un nom neutre, avec une majuscule ; *beim* = *bei dem*.","type":"choix","options":[{"id":"a","texte":"Beim Lesen ich höre Musik."},{"id":"b","texte":"Beim Lesen höre Musik ich."},{"id":"c","texte":"Bei Lesen höre ich Musik."},{"id":"d","texte":"Beim Lesen höre ich Musik."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r3c2"]},"explication":"*gleichzeitig* est un adverbe : il demande l’**inversion** (le verbe passe avant le sujet)."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0"}},"explication":"Quand les deux actions **s’opposent** (sport/lecture, ville qui grandit/village qui rétrécit), *während* = tandis que ; quand elles sont **simultanées**, *während* = pendant que."},{"cle":{"type":"ordre","ids":["g","b","c","a","f","d","e"]},"explication":"**Bei den Hausaufgaben hört er Musik; währenddessen sieht seine Schwester fern.** Après le groupe de tête et après l’adverbe *währenddessen*, le verbe vient avant le sujet."},{"cle":{"type":"trous","trous":[["des"]]},"affichage":"des","explication":"**während des Unterrichts** : préposition + génitif masculin (*des* + nom en *-s*)."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Beim Lesen höre ich Musik.** *Lesen* prend une majuscule, et le verbe conjugué est en 2e position."}]$ex$::jsonb),
  ('b008759b-3def-5f0d-b9e6-903018fc285f'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Les réseaux sociaux : pour et contre","competence":"argumenter","situation":"Mathis prépare un petit paragraphe sur les réseaux sociaux pour son cours d’allemand. Observe ses connecteurs.","documents":[{"id":"text","type":"texte","genre":"article","titre":"Soziale Netzwerke","blocs":["Soziale Netzwerke sind zwar praktisch, aber sie können süchtig machen. Außerdem verbreiten sich Falschmeldungen sehr schnell."],"source":"Texte écrit pour l’exercice, d’après le cours"}],"questions":[{"enonce":"Touche le mot qui annonce une concession, avant le « aber ».","aide":"*zwar … aber* veut dire « certes… mais ».","type":"zone","document":"text","multiple":false},{"enonce":"Range ces connecteurs selon leur nature, donc selon la place du verbe.","aide":"Un coordonnant ne change pas l’ordre des mots ; un adverbe est en position 1 et le verbe vient juste après.","type":"categories","categories":[{"id":"c0","texte":"Coordonnant (ordre normal)"},{"id":"c1","texte":"Adverbe (inversion)"},{"id":"c2","texte":"Subordonnant (verbe à la fin)"}],"items":[{"id":"i0","texte":"obwohl"},{"id":"i1","texte":"deshalb"},{"id":"i2","texte":"während"},{"id":"i3","texte":"denn"},{"id":"i4","texte":"trotzdem"},{"id":"i5","texte":"aber"}]},{"enonce":"Complète la phrase : « Ce n’est pas cher, c’est bon marché. »","aide":"Après une négation, on corrige : « mais au contraire ».","type":"trous","segments":["Das ist nicht teuer, ",0," billig."],"banque":["sondern","trotzdem","obwohl","zwar"]},{"enonce":"Relie chaque connecteur à sa traduction.","aide":"*anders* veut dire « autrement ».","type":"association","gauche":[{"id":"g0","texte":"außerdem"},{"id":"g1","texte":"übrigens"},{"id":"g2","texte":"zum Beispiel"},{"id":"g3","texte":"anders gesagt"}],"droite":[{"id":"d0","texte":"autrement dit"},{"id":"d1","texte":"d’ailleurs, au fait"},{"id":"d2","texte":"par exemple"},{"id":"d3","texte":"de plus"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3"]},"explication":"**zwar** : « certes ». On reconnaît un avantage avant de le nuancer avec *aber*."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c1","i2":"c2","i3":"c0","i4":"c1","i5":"c0"}},"explication":"**Coordonnants** : aber, denn. **Adverbes** : trotzdem, deshalb. **Subordonnants** : obwohl, während."},{"cle":{"type":"trous","trous":[["sondern"]]},"affichage":"sondern","explication":"**sondern** : « mais » après une négation (*nicht teuer, sondern billig*)."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g2":"d2","g0":"d3"}},"explication":"**außerdem** = de plus, **übrigens** = d’ailleurs, **zum Beispiel (z. B.)** = par exemple, **anders gesagt** = autrement dit."}]$ex$::jsonb),
  ('b008759b-3def-5f0d-b9e6-903018fc285f'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Se promener sous la pluie","competence":"manier-langue","situation":"Anna et Ben hésitent à sortir malgré la pluie. Lis leur échange, puis exerce-toi à exprimer la même idée de plusieurs façons.","documents":[{"id":"chat","type":"dialogue","modele":"sms","titre":"Nachrichten","participants":[{"nom":"Anna","emoji":"👧","cote":"gauche"},{"nom":"Ben","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Anna","texte":"Obwohl es regnet, gehen wir spazieren. Kommst du mit?"},{"qui":"Ben","texte":"Trotz des Regens? Das ist zwar mutig, aber ich komme mit."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le subordonnant qui introduit la concession et rejette le verbe à la fin.","aide":"Le mot est en tête du message d’Anna ; son verbe « regnet » est à la fin de la subordonnée.","type":"zone","document":"chat","multiple":false},{"enonce":"Touche le mot qui prépare le « aber » dans le message de Ben.","aide":"Il veut dire « certes ».","type":"zone","document":"chat","multiple":false},{"enonce":"Dis la même idée avec un adverbe. Le premier groupe est « Es regnet, ».","aide":"Après *trotzdem*, le verbe conjugué vient juste après, avant le sujet.","type":"ordre","items":[{"id":"a","texte":"wir"},{"id":"b","texte":"gehen"},{"id":"c","texte":"spazieren"},{"id":"d","texte":"trotzdem"},{"id":"e","texte":"Es regnet,"}]},{"enonce":"Range ces connecteurs selon ce qu’ils expriment.","aide":"*trotz* veut dire « malgré » ; *Gegensatz*, « contraire ».","type":"categories","categories":[{"id":"c0","texte":"Concession"},{"id":"c1","texte":"Opposition"},{"id":"c2","texte":"Ajout"}],"items":[{"id":"i0","texte":"obwohl"},{"id":"i1","texte":"im Gegensatz zu"},{"id":"i2","texte":"außerdem"},{"id":"i3","texte":"dagegen"},{"id":"i4","texte":"darüber hinaus"},{"id":"i5","texte":"trotzdem"}]},{"enonce":"Complète avec la préposition qui veut dire « malgré ».","aide":"Le groupe nominal « des Regens » est au génitif : il faut une préposition.","type":"trous","segments":[0," des Regens gehen wir spazieren."],"banque":["Trotzdem","Obwohl","Dagegen","Trotz"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m0"]},"explication":"**Obwohl** : « bien que », suivi du verbe en fin de subordonnée (*es regnet*)."},{"cle":{"type":"zone","ids":["m14"]},"explication":"**zwar … aber** : « certes… mais »."},{"cle":{"type":"ordre","ids":["e","d","b","a","c"]},"explication":"**Es regnet, trotzdem gehen wir spazieren.** *trotzdem* est un adverbe : il provoque l’inversion."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c2","i3":"c1","i4":"c2","i5":"c0"}},"explication":"**Concession** : obwohl, trotzdem. **Opposition** : dagegen, im Gegensatz zu. **Ajout** : außerdem, darüber hinaus."},{"cle":{"type":"trous","trous":[["trotz"]]},"affichage":"Trotz","explication":"**Trotz** + génitif = malgré. *Obwohl* et *trotzdem* introduiraient un verbe conjugué."}]$ex$::jsonb),
  ('b008759b-3def-5f0d-b9e6-903018fc285f'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Faut-il autoriser les portables au lycée ?","competence":"argumenter","situation":"Le délégué de classe de Nora écrit un paragraphe argumenté sur le portable en cours. Elle le relit avec le tableau des trois façons d’exprimer une concession.","documents":[{"id":"absatz","type":"texte","genre":"article","titre":"Handys in der Schule","blocs":["Einerseits sind Handys im Unterricht nützlich: Man kann schnell etwas nachschlagen. Andererseits lenken sie ab.","Außerdem sind viele Schüler abhängig. Zusammenfassend kann man sagen, dass Handys nur mit klaren Regeln erlaubt sein sollten."],"source":"Texte écrit pour l’exercice"},{"id":"tab","type":"tableau","titre":"Eine Idee, drei Konstruktionen","colonnes":["Connecteur","Nature","Place du verbe"],"lignes":[["obwohl","subordonnant","à la fin"],["trotzdem","adverbe","juste après lui"],["trotz + génitif","préposition","pas de verbe conjugué"]],"enteteLignes":true,"source":"Tableau tiré du cours"}],"questions":[{"enonce":"Touche le connecteur d’ajout qui est suivi du verbe, puis du sujet (inversion).","aide":"Il ouvre le deuxième paragraphe : « sind viele Schüler » vient après lui.","type":"zone","document":"absatz","multiple":false},{"enonce":"Remets les mots dans l’ordre : « Pour conclure, on peut dire que… » Le premier groupe est « Zusammenfassend ».","aide":"Après l’adverbe de tête, le verbe vient en deuxième position ; la subordonnée en *dass* suit.","type":"ordre","items":[{"id":"a","texte":"kann"},{"id":"b","texte":"man"},{"id":"c","texte":"Zusammenfassend"},{"id":"d","texte":"sagen,"},{"id":"e","texte":"dass"}]},{"enonce":"Quelle phrase exprime la même idée que « Obwohl es regnet, gehen wir spazieren » ?","aide":"Le tableau montre trois constructions pour la même concession : *obwohl*, *trotzdem*, *trotz*.","type":"choix","options":[{"id":"a","texte":"Trotz des Regens gehen wir spazieren."},{"id":"b","texte":"Trotzdem es regnet, gehen wir spazieren."},{"id":"c","texte":"Wegen des Regens gehen wir spazieren."},{"id":"d","texte":"Obwohl des Regens gehen wir spazieren."}],"multiple":false},{"enonce":"Relie chaque expression de l’argumentation à sa fonction.","aide":"*d. h.* est l’abréviation de *das heißt*.","type":"association","gauche":[{"id":"g0","texte":"einerseits"},{"id":"g1","texte":"andererseits"},{"id":"g2","texte":"zusammenfassend"},{"id":"g3","texte":"d. h."}],"droite":[{"id":"d0","texte":"pour conclure"},{"id":"d1","texte":"c’est-à-dire"},{"id":"d2","texte":"d’un côté"},{"id":"d3","texte":"de l’autre côté"}]},{"enonce":"Complète avec le connecteur qui veut dire « quand même ».","aide":"Après la virgule, le verbe « geht » vient juste après le mot cherché.","type":"trous","segments":["Er ist krank, ",0," geht er zur Arbeit."],"banque":["dagegen","trotzdem","obwohl","trotz"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m15"]},"explication":"**Außerdem** : adverbe d’ajout, donc verbe en 2e position et sujet après (*sind viele Schüler*)."},{"cle":{"type":"ordre","ids":["c","a","b","d","e"]},"explication":"**Zusammenfassend kann man sagen, dass …** : inversion après l’adverbe, puis subordonnée avec le verbe à la fin."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Trotz des Regens gehen wir spazieren.** : *trotz* + génitif, sans verbe conjugué dans le complément."},{"cle":{"type":"association","paires":{"g2":"d0","g3":"d1","g0":"d2","g1":"d3"}},"explication":"**einerseits** = d’un côté, **andererseits** = de l’autre, **zusammenfassend** = pour conclure, **d. h.** = c’est-à-dire."},{"cle":{"type":"trous","trous":[["trotzdem"]]},"affichage":"trotzdem","explication":"**trotzdem** : adverbe, donc inversion (*trotzdem geht er*). *obwohl* enverrait le verbe à la fin."}]$ex$::jsonb),
  ('b1db55e3-10c0-5572-8850-c6668b37cc1f'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Où est Tom ?","competence":"comprendre-langue","situation":"Tom est absent. Lisa et Jonas essaient de deviner pourquoi. Lis leur conversation.","documents":[{"id":"chat","type":"dialogue","modele":"sms","titre":"Nachrichten","participants":[{"nom":"Lisa","emoji":"👧","cote":"gauche"},{"nom":"Jonas","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lisa","texte":"Tom ist nicht in der Schule. Er muss krank sein."},{"qui":"Jonas","texte":"Das mag sein, aber gestern war er noch gesund."},{"qui":"Lisa","texte":"Dann dürfte er einen Termin beim Arzt haben."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le verbe de modalité qui exprime ici une supposition presque certaine, et non une obligation.","aide":"Lisa ne dit pas ce que Tom doit faire : elle devine ce qui est probable.","type":"zone","document":"chat","multiple":false},{"enonce":"Touche le verbe de modalité de la formule qui concède un point avant de le réfuter.","aide":"La formule est « Das … sein, aber… ».","type":"zone","document":"chat","multiple":false},{"enonce":"Relie chaque modal au degré de certitude qu’il exprime.","aide":"L’échelle va de « presque certain » à « impossible ».","type":"association","gauche":[{"id":"g0","texte":"muss"},{"id":"g1","texte":"dürfte"},{"id":"g2","texte":"könnte"},{"id":"g3","texte":"kann nicht"}],"droite":[{"id":"d0","texte":"impossible"},{"id":"d1","texte":"presque certain"},{"id":"d2","texte":"très probable"},{"id":"d3","texte":"possible"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7"]},"explication":"**muss** : emploi subjectif, « il doit être malade » = il est sûrement malade."},{"cle":{"type":"zone","ids":["m11"]},"explication":"**mag** : *Das mag sein, aber…* = « C’est possible, mais… »."},{"cle":{"type":"association","paires":{"g3":"d0","g0":"d1","g1":"d2","g2":"d3"}},"explication":"**muss** (presque certain), **dürfte** (très probable), **könnte** (possible), **kann nicht** (impossible)."}]$ex$::jsonb),
  ('b1db55e3-10c0-5572-8850-c6668b37cc1f'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le silence du père","competence":"analyser-texte","situation":"En cours, Marta commente une scène où un père se tait. Elle doit dire ce qu’elle suppose, avec le bon degré de certitude.","documents":[{"id":"kommentar","type":"texte","genre":"article","titre":"Kommentar zur Szene","blocs":["Der Vater schweigt, als die Polizei kommt. Warum sagt er nichts?","Er muss Angst gehabt haben. Vielleicht wollte er aber auch seine Familie schützen."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche l’adverbe qui exprime une simple possibilité (« peut-être »).","aide":"Il ouvre la deuxième phrase du dernier paragraphe.","type":"zone","document":"kommentar","multiple":false},{"enonce":"Complète : « Il a sûrement eu peur. »","aide":"Pour juger un fait passé, le modal reste au présent et l’infinitif devient passé : participe + *haben*.","type":"trous","segments":["Er muss Angst ",0," ",1,"."],"banque":["gehabt","sein","gewesen","haben"]},{"enonce":"Le modal exprime-t-il une obligation, une permission ou une capacité (emploi objectif), ou une supposition du locuteur (emploi subjectif) ?","aide":"Se demander : « est-ce une règle ou une capacité ? » ou « est-ce ce que je pense probable ? ».","type":"categories","categories":[{"id":"c0","texte":"Emploi objectif"},{"id":"c1","texte":"Emploi subjectif"}],"items":[{"id":"i0","texte":"Er muss um 8 Uhr arbeiten."},{"id":"i1","texte":"Er muss müde sein."},{"id":"i2","texte":"Sie kann gut schwimmen."},{"id":"i3","texte":"Du darfst hier parken."},{"id":"i4","texte":"Sie kann den Bus verpasst haben."},{"id":"i5","texte":"Das dürfte stimmen."}]},{"enonce":"Comment dit-on « Vous n’avez pas le droit de fumer ici » ?","aide":"*muss nicht* ne veut pas dire « ne doit pas » : il exprime l’absence d’obligation.","type":"choix","options":[{"id":"a","texte":"Sie müssen hier nicht rauchen."},{"id":"b","texte":"Sie sollten hier nicht rauchen."},{"id":"c","texte":"Sie dürfen hier nicht rauchen."},{"id":"d","texte":"Sie können hier nicht rauchen."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m16"]},"explication":"**Vielleicht** : « peut-être », une hypothèse moins sûre que « Er muss Angst gehabt haben »."},{"cle":{"type":"trous","trous":[["gehabt"],["haben"]]},"affichage":"gehabt · haben","explication":"**Er muss Angst gehabt haben.** Modal au présent + infinitif passé (*gehabt haben*)."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c0","i4":"c1","i5":"c1"}},"explication":"**Objectif** : obligation (*muss arbeiten*), capacité (*kann schwimmen*), permission (*darfst parken*). **Subjectif** : *muss … sein*, *kann … verpasst haben*, *dürfte stimmen*."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Sie dürfen hier nicht rauchen.** L’interdiction se dit avec *dürfen nicht* ; *müssen nicht* = « n’être pas obligé de »."}]$ex$::jsonb),
  ('b1db55e3-10c0-5572-8850-c6668b37cc1f'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le vélo disparu","competence":"argumenter","situation":"Mara a perdu son vélo et mène l’enquête avec Ole. Chacun avance des hypothèses : place-les sur l’échelle de certitude.","documents":[{"id":"chat","type":"dialogue","modele":"sms","titre":"Nachrichten","participants":[{"nom":"Mara","emoji":"👩","cote":"gauche"},{"nom":"Ole","emoji":"👨","cote":"droite"}],"repliques":[{"qui":"Mara","texte":"Mein Fahrrad ist weg! Wer hat es nur genommen?"},{"qui":"Ole","texte":"Der Nachbar ist verreist. Das kann er nicht gewesen sein."},{"qui":"Mara","texte":"Vielleicht war es Paul. Er braucht doch ein Rad."},{"qui":"Ole","texte":"Das könnte sein, aber Paul war gestern den ganzen Tag bei mir."},{"qui":"Mara","texte":"Dann muss es ein Fremder gewesen sein."}],"source":"Messages écrits pour l’exercice"},{"id":"skala","type":"tableau","titre":"Skala der Sicherheit","colonnes":["Adverbe","Degré de certitude"],"lignes":[["bestimmt, sicher","certain"],["wahrscheinlich","probable"],["vielleicht","peut-être"],["kaum","à peine"]],"enteteLignes":true,"source":"Tableau tiré du cours"}],"questions":[{"enonce":"Touche le modal par lequel Ole exclut que le voisin soit le voleur.","aide":"Ole dit que c’est impossible.","type":"zone","document":"chat","multiple":false},{"enonce":"Touche le modal par lequel Ole admet seulement que ce serait possible, sans plus.","aide":"Le mot est au subjonctif II et exprime une simple possibilité.","type":"zone","document":"chat","multiple":false},{"enonce":"Que conclut Mara à la fin de la conversation ?","aide":"Relis sa dernière phrase : *muss … gewesen sein* exprime une quasi-certitude.","type":"choix","options":[{"id":"a","texte":"Elle croit que le vélo est resté chez le voisin"},{"id":"b","texte":"Elle est presque sûre que c’était un inconnu"},{"id":"c","texte":"Elle pense que personne ne l’a pris"},{"id":"d","texte":"Elle pense que c’est Paul, sans aucun doute"}],"multiple":false},{"enonce":"Range ces adverbes du moins sûr au plus sûr, d’après le tableau. Le premier est « kaum ».","aide":"Le tableau les range du plus sûr au moins sûr : lis-le à l’envers.","type":"ordre","items":[{"id":"a","texte":"kaum"},{"id":"b","texte":"wahrscheinlich"},{"id":"c","texte":"vielleicht"},{"id":"d","texte":"bestimmt"}]},{"enonce":"Relie chaque phrase allemande à sa traduction.","aide":"Pour le passé, le modal reste au présent et l’infinitif passe au passé.","type":"association","gauche":[{"id":"g0","texte":"Er muss krank gewesen sein."},{"id":"g1","texte":"Sie kann den Bus verpasst haben."},{"id":"g2","texte":"Das dürfte schwierig gewesen sein."},{"id":"g3","texte":"Das kann nicht sein!"}],"droite":[{"id":"d0","texte":"Elle a pu rater le bus."},{"id":"d1","texte":"Ça a dû être difficile."},{"id":"d2","texte":"Ce n’est pas possible !"},{"id":"d3","texte":"Il a sûrement été malade."}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m14"]},"explication":"**kann … nicht gewesen sein** : « ce n’est pas possible que ce soit lui ». Le modal reste au présent, l’infinitif est au passé."},{"cle":{"type":"zone","ids":["m29"]},"explication":"**könnte** : « ça pourrait être vrai », le degré « possible » de l’échelle."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Dann muss es ein Fremder gewesen sein.** : « ce doit être un inconnu » (presque certain)."},{"cle":{"type":"ordre","ids":["a","c","b","d"]},"explication":"**kaum** (à peine) → **vielleicht** (peut-être) → **wahrscheinlich** (probable) → **bestimmt** (certain)."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"**muss** = presque certain, **kann** = possible, **dürfte** = très probable, **kann nicht** = impossible."}]$ex$::jsonb)
) AS v (chapter_id, position, etoiles, gemmes, xp, nb_questions, contenu, cles);

INSERT INTO public.exercices (id, chapter_id, position, etoiles, gemmes, xp, nb_questions, contenu)
SELECT s.id, s.chapter_id, s.position, s.etoiles, s.gemmes, s.xp, s.nb_questions, s.contenu
FROM exercices_seed s
JOIN public.chapters c ON c.id = s.chapter_id
ON CONFLICT (id) DO UPDATE
  SET etoiles      = EXCLUDED.etoiles,
      nb_questions = EXCLUDED.nb_questions,
      contenu      = EXCLUDED.contenu,
      updated_at   = now();

INSERT INTO public.exercices_cles (exercice_id, cles)
SELECT s.id, s.cles
FROM exercices_seed s
JOIN public.exercices e ON e.id = s.id
ON CONFLICT (exercice_id) DO UPDATE SET cles = EXCLUDED.cles;

-- Contrôle : combien d'exercices de ce fichier sont en base, et combien sautés.
DO $$
DECLARE
  v_attendus INTEGER;
  v_poses    INTEGER;
BEGIN
  SELECT count(*) INTO v_attendus FROM exercices_seed;
  SELECT count(*) INTO v_poses FROM public.exercices e JOIN exercices_seed s ON s.id = e.id;
  RAISE NOTICE 'Cahier 1re (3) : % exercices posés sur % (les autres n''ont pas leur chapitre en base).', v_poses, v_attendus;
  DROP TABLE IF EXISTS pg_temp.exercices_seed;
END $$;
